        <span>\(f(x) = x^3\)</span>
      </div>
      <div style="display: flex; align-items: center; gap: 6px;">
        <span style="width: 12px; height: 3px; background: #ef4444; border-radius: 2px; display: inline-block;"></span>
        <span>\(g(x) = x\)</span>
      </div>
      <div style="display: flex; align-items: center; gap: 6px;">
        <span style="width: 12px; height: 12px; background: rgba(168, 85, 247, 0.35); border: 1px solid #a855f7; border-radius: 3px; display: inline-block;"></span>
        <span>Área \(A = \frac{1}{2}\)</span>
      </div>
    </div>
  </div>
</div>

<script>
  (function() {
    function renderGraph() {
      const canvas = document.getElementById('canvasPaso3');
      if (!canvas) return setTimeout(renderGraph, 50);
      const ctx = canvas.getContext('2d');
      const w = canvas.width, h = canvas.height, s = 90, cx = w / 2, cy = h / 2;

      const mX = x => cx + x * s;
      const mY = y => cy - y * s;
      const f = x => Math.pow(x, 3);
      const g = x => x;

      ctx.clearRect(0, 0, w, h);

      // 1. Cuadrícula tenue
      ctx.beginPath();
      ctx.strokeStyle = '#f1f5f9';
      ctx.lineWidth = 1;
      for (let i = -2; i <= 2; i += 0.5) {
        ctx.moveTo(mX(i), 0); ctx.lineTo(mX(i), h);
        ctx.moveTo(0, mY(i)); ctx.lineTo(w, mY(i));
      }
      ctx.stroke();

      // 2. Ejes cartesianos
      ctx.beginPath();
      ctx.strokeStyle = '#64748b';
      ctx.lineWidth = 1.5;
      ctx.moveTo(0, cy); ctx.lineTo(w, cy);
      ctx.moveTo(cx, 0); ctx.lineTo(cx, h);
      ctx.stroke();

      // 3. Sombreado del área entre las dos curvas (Morado traslúcido)
      const drawArea = (startX, endX, topFunc, botFunc) => {
        ctx.beginPath();
        ctx.fillStyle = 'rgba(168, 85, 247, 0.35)';
        // Trazar techo (ida)
        for (let x = startX; x <= endX + 0.01; x += 0.03) {
          if (Math.abs(x - startX) < 0.001) ctx.moveTo(mX(x), mY(topFunc(x)));
          else ctx.lineTo(mX(x), mY(topFunc(x)));
        }
        // Trazar piso (vuelta)
        for (let x = endX; x >= startX - 0.01; x -= 0.03) {
          ctx.lineTo(mX(x), mY(botFunc(x)));
        }
        ctx.closePath();
        ctx.fill();
      };

      drawArea(-1, 0, f, g); // Tramo 1 [-1, 0]: f es techo
      drawArea(0, 1, g, f);  // Tramo 2 [0, 1]: g es techo

      // 4. Dibujar curvas principales encima del sombreado
      const drawCurve = (fn, col) => {
        ctx.beginPath();
        ctx.strokeStyle = col;
        ctx.lineWidth = 2.5;
        for (let x = -1.5; x <= 1.5; x += 0.03) {
          if (x === -1.5) ctx.moveTo(mX(x), mY(fn(x)));
          else ctx.lineTo(mX(x), mY(fn(x)));
        }
        ctx.stroke();
      };

      drawCurve(f, '#3b82f6'); // f(x) Azul
      drawCurve(g, '#ef4444'); // g(x) Rojo

      // 5. Puntos de intersección (-1,-1), (0,0), (1,1)
      const drawP = (x, y) => {
        ctx.beginPath();
        ctx.arc(mX(x), mY(y), 5.5, 0, 2 * Math.PI);
        ctx.fillStyle = '#10b981';
        ctx.fill();
        ctx.strokeStyle = '#0f766e';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      };

      drawP(-1, -1);
      drawP(0, 0);
      drawP(1, 1);
    }

    renderGraph();
  })();
</script>
