    const canvas = document.getElementById('canvasAnimado');
    const ctx = canvas.getContext('2d');

    const elemFormula = document.getElementById('formula-principal');
    const elemTiempo = document.getElementById('tiempo-vivo');
    const elemEjeX = document.getElementById('eje-x');

    let t = 0; // Tiempo inicial
    const origenX = 50;  // Posición del eje Y en pantalla
    const origenY = 175; // Posición del eje X en pantalla (centro vertical)
    const escalaX = 45;  // Píxeles por unidad en X
    const escalaY = 80;  // Píxeles por unidad en Y (amplitud)

    function iniciarAnimacion() {
        // Verificar si KaTeX ya cargó desde la red
        if (window.katex) {
            katex.render("f(x, t) = \\sin(2x - t)", elemFormula);
            katex.render("x \\rightarrow", elemEjeX);
        } else {
            setTimeout(iniciarAnimacion, 100);
            return;
        }

        // Bucle de animación continuo
        function animar() {
            // A. Limpiar el canvas antes de dibujar el nuevo fotograma
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // B. Dibujar los ejes cartesianos
            ctx.beginPath();
            ctx.strokeStyle = "#45475a";
            ctx.lineWidth = 1;
            // Eje X
            ctx.moveTo(0, origenY); 
            ctx.lineTo(canvas.width, origenY);
            // Eje Y
            ctx.moveTo(origenX, 0); 
            ctx.lineTo(origenX, canvas.height);
            ctx.stroke();

            // C. Dibujar la curva matemática animada
            ctx.beginPath();
            ctx.strokeStyle = "#f38ba8"; // Color rosa neón
            ctx.lineWidth = 3;

            for (let px = 0; px <= (canvas.width - origenX); px++) {
                let x = px / escalaX;
                let y = Math.sin(2 * x - t);
                let py = origenY - (y * escalaY);

                if (px === 0) {
                    ctx.moveTo(origenX + px, py);
                } else {
                    ctx.lineTo(origenX + px, py);
                }
            }
            ctx.stroke();

            // D. Actualizar la etiqueta de tiempo en vivo con KaTeX
            if (window.katex) {
                katex.render(`t = ${t.toFixed(2)} \\text{ s}`, elemTiempo);
            }

            // E. Incrementar el tiempo para la onda
            t += 0.04;

            // F. Siguiente fotograma de animación
            requestAnimationFrame(animar);
        }

        animar();
    }

    iniciarAnimacion();
</script>
