<script>
  (function() {
    let isOrbiting = false;
    let animId = null;

    function renderGraph() {
      const canvas = document.getElementById('canvasSumaR3');
      const btn = document.getElementById('btnOrbitR3');
      const rangeYaw = document.getElementById('rangeYawR3');
      const txtYaw = document.getElementById('txtYawR3');

      if (!canvas || !btn || !rangeYaw) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2 + 50;
      const scale = 48;

      // Proyección Isométrica Dinámica en 3D
      function project3D(x, y, z, yawDeg) {
        const yaw = (yawDeg * Math.PI) / 180;
        // Rotación alrededor del Eje Z (Yaw)
        const rx = x * Math.cos(yaw) - y * Math.sin(yaw);
        const ry = x * Math.sin(yaw) + y * Math.cos(yaw);
        const rz = z;

        // Proyección Isométrica 2D
        const px = cx + (ry - rx) * 0.866 * scale;
        const py = cy + (rx + ry) * 0.5 * scale - rz * scale;
        return { px, py };
      }

      function drawArrow3D(p1Math, p2Math, col, widthLine = 2.5, yawDeg) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z, yawDeg);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z, yawDeg);
        const angle = Math.atan2(p2.py - p1.py, p2.px - p1.px);
        const headLen = 10;

        ctx.beginPath();
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(p2.px, p2.py);
        ctx.lineTo(p2.px - headLen * Math.cos(angle - 0.35), p2.py - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.px - headLen * Math.cos(angle + 0.35), p2.py - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawDashLine3D(p1Math, p2Math, col = '#64748b', yawDeg) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z, yawDeg);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z, yawDeg);

        ctx.beginPath();
        ctx.setLineDash([4, 4]);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = 1.3;
        ctx.stroke();
        ctx.setLineDash([]);
      }

      function drawPoint3D(pMath, col, yawDeg) {
        const p = project3D(pMath.x, pMath.y, pMath.z, yawDeg);
        ctx.beginPath();
        ctx.arc(p.px, p.py, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        const yawDeg = parseFloat(rangeYaw.value);
        txtYaw.textContent = `${Math.round(yawDeg)}°`;

        ctx.clearRect(0, 0, width, height);

        const O = { x: 0, y: 0, z: 0 };
        const A = { x: 1, y: 0, z: 0 };
        const B = { x: 0, y: 2, z: 3 };
        const C = { x: 1, y: 2, z: 3 }; // A + B

        // Puntos auxiliares del paralelepípedo
        const B_xy = { x: 0, y: 2, z: 0 };
        const C_xy = { x: 1, y: 2, z: 0 };
        const A_z = { x: 1, y: 0, z: 3 };

        // 1. Ejes Cartesiano 3D (X, Y, Z)
        drawArrow3D(O, { x: 3.5, y: 0, z: 0 }, '#475569', 1.5, yawDeg);
        drawArrow3D(O, { x: 0, y: 3.5, z: 0 }, '#475569', 1.5, yawDeg);
        drawArrow3D(O, { x: 0, y: 0, z: 4.2 }, '#475569', 1.5, yawDeg);

        // Etiquetas Ejes
        const pX = project3D(3.7, 0, 0, yawDeg);
        const pY = project3D(0, 3.7, 0, yawDeg);
        const pZ = project3D(0, 0, 4.4, yawDeg);

        ctx.fillStyle = '#94a3b8';
        ctx.font = 'bold 12px sans-serif';
        ctx.fillText('x', pX.px, pX.py);
        ctx.fillText('y', pY.px, pY.py);
        ctx.fillText('z', pZ.px, pZ.py);

        // 2. Caras translúcidas del Paralelepípedo
        const pO = project3D(O.x, O.y, O.z, yawDeg);
        const pA = project3D(A.x, A.y, A.z, yawDeg);
        const pB = project3D(B.x, B.y, B.z, yawDeg);
        const pC = project3D(C.x, C.y, C.z, yawDeg);
        const pCxy = project3D(C_xy.x, C_xy.y, C_xy.z, yawDeg);
        const pBxy = project3D(B_xy.x, B_xy.y, B_xy.z, yawDeg);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(56, 189, 248, 0.08)';
        ctx.moveTo(pO.px, pO.py);
        ctx.lineTo(pA.px, pA.py);
        ctx.lineTo(pCxy.px, pCxy.py);
        ctx.lineTo(pBxy.px, pBxy.py);
        ctx.closePath();
        ctx.fill();

        ctx.beginPath();
        ctx.fillStyle = 'rgba(52, 211, 153, 0.08)';
        ctx.moveTo(pB.px, pB.py);
        ctx.lineTo(pC.px, pC.py);
        ctx.lineTo(pCxy.px, pCxy.py);
        ctx.lineTo(pBxy.px, pBxy.py);
        ctx.closePath();
        ctx.fill();

        // 3. Aristas de Proyección del Paralelepípedo
        drawDashLine3D(A, C_xy, '#64748b', yawDeg);
        drawDashLine3D(B_xy, C_xy, '#64748b', yawDeg);
        drawDashLine3D(C_xy, C, '#64748b', yawDeg);
        drawDashLine3D(B_xy, B, '#64748b', yawDeg);
        drawDashLine3D(A, C, '#64748b', yawDeg);
        drawDashLine3D(B, C, '#64748b', yawDeg);

        // 4. Vector a (Azul Neón)
        drawArrow3D(O, A, '#38bdf8', 3, yawDeg);
        drawPoint3D(A, '#0284c7', yawDeg);

        // 5. Vector b (Rosa Neón)
        drawArrow3D(O, B, '#f43f5e', 3, yawDeg);
        drawPoint3D(B, '#e11d48', yawDeg);

        // 6. Vector Suma a + b (Verde Esmeralda)
        drawArrow3D(O, C, '#34d399', 3.5, yawDeg);
        drawPoint3D(C, '#10b981', yawDeg);
        drawPoint3D(O, '#94a3b8', yawDeg);
      }

      // Animación de rotación automática
      function animateOrbit() {
        let current = parseFloat(rangeYaw.value);
        current = (current + 0.8) % 360;
        rangeYaw.value = current;
        draw();
        if (isOrbiting) {
          animId = requestAnimationFrame(animateOrbit);
        }
      }

      btn.onclick = () => {
        if (isOrbiting) {
          isOrbiting = false;
          cancelAnimationFrame(animId);
          btn.innerHTML = '🔄 Rotar Vista 3D';
        } else {
          isOrbiting = true;
          btn.innerHTML = '⏸ Pausar Giro';
          animateOrbit();
        }
      };

      rangeYaw.oninput = () => {
        if (isOrbiting) {
          isOrbiting = false;
          cancelAnimationFrame(animId);
          btn.innerHTML = '🔄 Rotar Vista 3D';
        }
        draw();
      };

      draw();
    }

    renderGraph();
  })();
</script>
\end{html}
