<script>
  (function() {
    function renderGraph() {
      const canvas = document.getElementById('canvasPonderacionR2');
      const rangeC = document.getElementById('rangeEscalarC');
      const txtC = document.getElementById('txtEscalarC');
      const btnReset = document.getElementById('btnResetEscalar');
      const lblCalculo = document.getElementById('lblEscalarCalculado');

      if (!canvas || !rangeC || !lblCalculo) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;

      const sc = 36; // 1 unidad matemática = 36px
      const cx = width / 2;  // Origen al centro X (270px)
      const cy = height / 2; // Origen al centro Y (180px)

      const pt = (x, y) => ({ x: cx + x * sc, y: cy - y * sc });

      function drawArrow(x1, y1, x2, y2, col, widthLine = 2.5, dash = []) {
        const p1 = pt(x1, y1), p2 = pt(x2, y2);
        const len = Math.hypot(p2.x - p1.x, p2.y - p1.y);
        if (len < 2) return; // Si es longitud cero (origen), no dibuja flecha

        const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        const headLen = Math.min(10, len);

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.x, p2.y);
        ctx.lineTo(p2.x - headLen * Math.cos(angle - 0.35), p2.y - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.x - headLen * Math.cos(angle + 0.35), p2.y - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawPoint(x, y, col = '#64748b') {
        const p = pt(x, y);
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        const cVal = parseFloat(rangeC.value);
        txtC.textContent = cVal.toFixed(1);

        // Actualizar fórmula en KaTeX dinámicamente si está cargado
        const resX = (2 * cVal).toFixed(1).replace('.0', '');
        const resY = (-1 * cVal).toFixed(1).replace('.0', '');
        const colTexto = cVal < 0 ? '#dc2626' : (cVal === 0 ? '#475569' : '#059669');

        lblCalculo.style.color = colTexto;
        if (window.katex) {
          katex.render(`c\\vec{u} = ${cVal.toFixed(1)} \\cdot (2, -1) = (${resX}, ${resY})`, lblCalculo);
        } else {
          lblCalculo.textContent = `c u = ${cVal.toFixed(1)} · (2, -1) = (${resX}, ${resY})`;
        }

        ctx.clearRect(0, 0, width, height);

        // 1. Cuadrícula tenue en los 4 cuadrantes
        ctx.beginPath();
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        for (let x = -7; x <= 7; x++) {
          ctx.moveTo(pt(x, -5).x, 0); ctx.lineTo(pt(x, -5).x, height);
        }
        for (let y = -5; y <= 5; y++) {
          ctx.moveTo(0, pt(-7, y).y); ctx.lineTo(width, pt(-7, y).y);
        }
        ctx.stroke();

        // 2. Ejes Cartesiano Cruz completa (X e Y)
        drawArrow(-7.2, 0, 7.2, 0, '#94a3b8', 1.5);
        drawArrow(0, -4.6, 0, 4.6, '#94a3b8', 1.5);

        // 3. Línea de Acción (Recta contenedora de todos los vectores colineales)
        ctx.beginPath();
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = '#cbd5e1';
        ctx.lineWidth = 1.3;
        ctx.moveTo(pt(-6, 3).x, pt(-6, 3).y);
        ctx.lineTo(pt(6, -3).x, pt(6, -3).y);
        ctx.stroke();
        ctx.setLineDash([]);

        // 4. Marcas de referencia estáticas: -u (-2, 1) y 2u (4, -2)
        drawArrow(0, 0, -2, 1, '#fca5a5', 1.5, [3, 3]);
        drawArrow(0, 0, 4, -2, '#a7f3d0', 1.5, [3, 3]);

        // 5. Vector Base u = (2, -1) [Azul Cobalt]
        drawArrow(0, 0, 2, -1, '#2563eb', 3);
        drawPoint(2, -1, '#1d4ed8');

        // 6. Vector Ponderado c*u (Dinámico)
        const targetX = 2 * cVal;
        const targetY = -1 * cVal;
        const colPonderado = cVal < 0 ? '#dc2626' : '#059669';

        if (Math.abs(cVal) > 0.05) {
          drawArrow(0, 0, targetX, targetY, colPonderado, 3.5);
          drawPoint(targetX, targetY, colPonderado);
        }

        // Origen destacado
        drawPoint(0, 0, '#475569');
      }

      rangeC.oninput = draw;
      btnReset.onclick = () => {
        rangeC.value = 2.0;
        draw();
      };

      draw();
    }

    renderGraph();
  })();
</script>
