<script>
  (function() {
    let isOrbiting = false;
    let animId = null;

    function renderGraph() {
      const canvas = document.getElementById('canvasPonderacionR3');
      const rangeC = document.getElementById('rangeEscalarC3D');
      const txtC = document.getElementById('txtEscalarC3D');
      const rangeYaw = document.getElementById('rangeYawR3Pond');
      const btnOrbit = document.getElementById('btnOrbitR3Pond');
      const lblCalculo = document.getElementById('lblCalculo3D');

      if (!canvas || !rangeC || !rangeYaw) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2 + 65;
      const scale = 22;

      // Proyección Isométrica Dinámica con Yaw
      function project3D(x, y, z, yawDeg) {
        const yaw = (yawDeg * Math.PI) / 180;
        const rx = x * Math.cos(yaw) - y * Math.sin(yaw);
        const ry = x * Math.sin(yaw) + y * Math.cos(yaw);
        const rz = z;

        const px = cx + (ry - rx) * 0.866 * scale;
        const py = cy + (rx + ry) * 0.5 * scale - rz * scale;
        return { px, py };
      }

      function drawArrow3D(p1Math, p2Math, col, widthLine = 2.5, yawDeg, dash = []) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z, yawDeg);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z, yawDeg);
        const len = Math.hypot(p2.px - p1.px, p2.py - p1.py);
        if (len < 2) return;

        const angle = Math.atan2(p2.py - p1.py, p2.px - p1.px);
        const headLen = Math.min(10, len);

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.px, p2.py);
        ctx.lineTo(p2.px - headLen * Math.cos(angle - 0.35), p2.py - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.px - headLen * Math.cos(angle + 0.35), p2.py - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawPoint3D(pMath, col, yawDeg) {
        const p = project3D(pMath.x, pMath.y, pMath.z, yawDeg);
        ctx.beginPath();
        ctx.arc(p.px, p.py, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        const cVal = parseFloat(rangeC.value);
        const yawDeg = parseFloat(rangeYaw.value);
        txtC.textContent = cVal.toFixed(1);

        // Formateo LaTeX sin \langle ni \rangle
        const rx = (4 * cVal).toFixed(1).replace('.0', '');
        const ry = (4 * cVal).toFixed(1).replace('.0', '');
        const rz = (8 * cVal).toFixed(1).replace('.0', '');

        if (window.katex) {
          katex.render(`${cVal.toFixed(1)}\\vec{v} = (${rx}, ${ry}, ${rz})`, lblCalculo);
        } else {
          lblCalculo.textContent = `${cVal.toFixed(1)}v = (${rx}, ${ry}, ${rz})`;
        }

        ctx.clearRect(0, 0, width, height);

        const O = { x: 0, y: 0, z: 0 };
        const BaseV = { x: 4, y: 4, z: 8 };
        const TargetV = { x: 4 * cVal, y: 4 * cVal, z: 8 * cVal };

        // 1. Ejes Cartesiano 3D (X, Y, Z)
        drawArrow3D(O, { x: 7, y: 0, z: 0 }, '#475569', 1.5, yawDeg);
        drawArrow3D(O, { x: 0, y: 7, z: 0 }, '#475569', 1.5, yawDeg);
        drawArrow3D(O, { x: 0, y: 0, z: 10 }, '#475569', 1.5, yawDeg);

        // Etiquetas de Ejes
        const pX = project3D(7.5, 0, 0, yawDeg);
        const pY = project3D(0, 7.5, 0, yawDeg);
        const pZ = project3D(0, 0, 10.5, yawDeg);

        ctx.fillStyle = '#94a3b8';
        ctx.font = 'bold 12px sans-serif';
        ctx.fillText('x', pX.px, pX.py);
        ctx.fillText('y', pY.px, pY.py);
        ctx.fillText('z', pZ.px, pZ.py);

        // 2. Recta de Acción 3D Punteada
        drawArrow3D({ x: -6, y: -6, z: -12 }, { x: 7, y: 7, z: 14 }, '#334155', 1.2, yawDeg, [4, 4]);

        // 3. Vector Base v = (4, 4, 8) en Azul Neón
        drawArrow3D(O, BaseV, '#38bdf8', 2.8, yawDeg);
        drawPoint3D(BaseV, '#0284c7', yawDeg);

        // 4. Vector Ponderado c*v en Amarillo Neón / Rojo según signo
        const colPond = cVal < 0 ? '#f43f5e' : '#facc15';
        if (Math.abs(cVal) > 0.05) {
          drawArrow3D(O, TargetV, colPond, 3.5, yawDeg);
          drawPoint3D(TargetV, colPond, yawDeg);
        }

        drawPoint3D(O, '#94a3b8', yawDeg);
      }

      function animateOrbit() {
        let current = parseFloat(rangeYaw.value);
        current = (current + 0.8) % 360;
        rangeYaw.value = current;
        draw();
        if (isOrbiting) animId = requestAnimationFrame(animateOrbit);
      }

      btnOrbit.onclick = () => {
        if (isOrbiting) {
          isOrbiting = false;
          cancelAnimationFrame(animId);
          btnOrbit.innerHTML = '🔄 Rotar 3D';
        } else {
          isOrbiting = true;
          btnOrbit.innerHTML = '⏸ Pausar';
          animateOrbit();
        }
      };

      rangeC.oninput = draw;
      rangeYaw.oninput = () => {
        if (isOrbiting) {
          isOrbiting = false;
          cancelAnimationFrame(animId);
          btnOrbit.innerHTML = '🔄 Rotar 3D';
        }
        draw();
      };

      draw();
    }

    renderGraph();
  })();
</script>
\end{html}

