      const btnOrbit = document.getElementById('btnOrbitR3Resta');
      const rangeYaw = document.getElementById('rangeYawR3Resta');

      if (!canvas || !btnMode || !rangeYaw) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2 + 50;
      const scale = 32;

      // Proyección Isométrica 3D
      function project3D(x, y, z, yawDeg) {
        const yaw = (yawDeg * Math.PI) / 180;
        const rx = x * Math.cos(yaw) - y * Math.sin(yaw);
        const ry = x * Math.sin(yaw) + y * Math.cos(yaw);
        const rz = z;

        const px = cx + (ry - rx) * 0.866 * scale;
        const py = cy + (rx + ry) * 0.5 * scale - rz * scale;
        return { px, py };
      }

      function drawArrow3D(p1Math, p2Math, col, widthLine = 2.5, yawDeg, dash = []) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z, yawDeg);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z, yawDeg);
        const len = Math.hypot(p2.px - p1.px, p2.py - p1.py);
        if (len < 2) return;

        const angle = Math.atan2(p2.py - p1.py, p2.px - p1.px);
        const headLen = Math.min(10, len);

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.px, p2.py);
        ctx.lineTo(p2.px - headLen * Math.cos(angle - 0.35), p2.py - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.px - headLen * Math.cos(angle + 0.35), p2.py - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawDashLine3D(p1Math, p2Math, col = '#475569', yawDeg) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z, yawDeg);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z, yawDeg);

        ctx.beginPath();
        ctx.setLineDash([4, 4]);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = 1.3;
        ctx.stroke();
        ctx.setLineDash([]);
      }

      function drawPoint3D(pMath, col, yawDeg) {
        const p = project3D(pMath.x, pMath.y, pMath.z, yawDeg);
        ctx.beginPath();
        ctx.arc(p.px, p.py, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        const yawDeg = parseFloat(rangeYaw.value);
        ctx.clearRect(0, 0, width, height);

        const O = { x: 0, y: 0, z: 0 };
        const P = { x: 2, y: 2, z: 5 };
        const Q = { x: 0, y: 0, z: 1 };
        const Diff = { x: -2, y: -2, z: -4 };

        // 1. Ejes Cartesiano 3D (X, Y, Z)
        drawArrow3D(O, { x: 4.5, y: 0, z: 0 }, '#475569', 1.5, yawDeg);
        drawArrow3D(O, { x: 0, y: 4.5, z: 0 }, '#475569', 1.5, yawDeg);
        drawArrow3D(O, { x: 0, y: 0, z: 6.5 }, '#475569', 1.5, yawDeg);

        // Etiquetas Ejes
        const pX = project3D(4.8, 0, 0, yawDeg);
        const pY = project3D(0, 4.8, 0, yawDeg);
        const pZ = project3D(0, 0, 6.8, yawDeg);

        ctx.fillStyle = '#94a3b8';
        ctx.font = 'bold 12px sans-serif';
        ctx.fillText('x', pX.px, pX.py);
        ctx.fillText('y', pY.px, pY.py);
        ctx.fillText('z', pZ.px, pZ.py);

        // 2. Proyecciones 3D de P(2,2,5)
        const P_xy = { x: 2, y: 2, z: 0 };
        drawDashLine3D({ x: 2, y: 0, z: 0 }, P_xy, '#334155', yawDeg);
        drawDashLine3D({ x: 0, y: 2, z: 0 }, P_xy, '#334155', yawDeg);
        drawDashLine3D(P_xy, P, '#38bdf8', yawDeg);

        // 3. Vector Posición P (Azul Neón)
        drawArrow3D(O, P, '#38bdf8', 2.5, yawDeg);
        drawPoint3D(P, '#0284c7', yawDeg);

        // 4. Vector Posición Q (Verde Esmeralda)
        drawArrow3D(O, Q, '#34d399', 2.5, yawDeg);
        drawPoint3D(Q, '#10b981', yawDeg);

        // 5. Vector Resta según el Modo seleccionado
        if (mode === 'desplazamiento') {
          // Vector Desplazamiento que parte desde P(2,2,5) hacia Q(0,0,1)
          drawArrow3D(P, Q, '#f43f5e', 3.5, yawDeg);
        } else {
          // Vector Resta trasladado al Origen (0,0,0) -> (-2, -2, -4)
          drawArrow3D(O, Diff, '#f43f5e', 3.5, yawDeg);
          drawPoint3D(Diff, '#e11d48', yawDeg);

          // Línea de traslación paralela
          drawDashLine3D(P, Q, '#fca5a5', yawDeg);
        }

        drawPoint3D(O, '#94a3b8', yawDeg);
      }

      function animateOrbit() {
        let current = parseFloat(rangeYaw.value);
        current = (current + 0.8) % 360;
        rangeYaw.value = current;
        draw();
        if (isOrbiting) animId = requestAnimationFrame(animateOrbit);
      }

      btnOrbit.onclick = () => {
        if (isOrbiting) {
          isOrbiting = false;
          cancelAnimationFrame(animId);
          btnOrbit.innerHTML = '🔄 Rotar 3D';
        } else {
          isOrbiting = true;
          btnOrbit.innerHTML = '⏸ Pausar';
          animateOrbit();
        }
      };

      btnMode.onclick = () => {
        if (mode === 'desplazamiento') {
          mode = 'origen';
          btnMode.innerHTML = '🔄 Alternar a Vector Desplazamiento P ➔ Q';
        } else {
          mode = 'desplazamiento';
          btnMode.innerHTML = '🔄 Alternar a Vector Posición en Origen';
        }
        draw();
      };

      rangeYaw.oninput = () => {
        if (isOrbiting) {
          isOrbiting = false;
          cancelAnimationFrame(animId);
          btnOrbit.innerHTML = '🔄 Rotar 3D';
        }
        draw();
      };

      draw();
    }

    renderGraph();
  })();
</script>
