    <button id="btnFullscreenGeo_Cross" style="padding: 6px 14px; background: #2563eb; color: white; border: none; border-radius: 6px; font-weight: 600; cursor: pointer; transition: all 0.2s;">
      ⛶ Pantalla Completa
    </button>
    <button id="btnResetGeo_Cross" style="padding: 6px 12px; background: #0f172a; color: white; border: none; border-radius: 6px; font-weight: 600; cursor: pointer;">
      ↺ Restablecer
    </button>
  </div>

  <!-- LEYENDA DE COLORES -->
  <div id="legendGeo3D_Cross" style="display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 16px; margin-top: 12px; font-size: 12px; font-weight: 600; color: #475569;">
    <div style="display: flex; align-items: center; gap: 6px;">
      <span style="width: 12px; height: 3px; background: #dc2626; border-radius: 2px; display: inline-block;"></span>
      <span>Vector \(\vec{u} = (2, 0, 0)\)</span>
    </div>
    <div style="display: flex; align-items: center; gap: 6px;">
      <span style="width: 12px; height: 3px; background: #059669; border-radius: 2px; display: inline-block;"></span>
      <span>Vector \(\vec{v} = (0, 2, 0)\)</span>
    </div>
    <div style="display: flex; align-items: center; gap: 6px;">
      <span style="width: 12px; height: 3px; background: #2563eb; border-radius: 2px; display: inline-block;"></span>
