<script>
  (function() {
    function renderGraph() {
      const container = document.getElementById('containerGeo3D_Cross');
      const wrapper = document.getElementById('wrapperCanvas3D_Cross');
      const canvas = document.getElementById('canvasGeoGebra3D_Cross');

      const btnViewX = document.getElementById('btnViewX_Cross');
      const btnViewY = document.getElementById('btnViewY_Cross');
      const btnViewZ = document.getElementById('btnViewZ_Cross');
      const btnFullscreen = document.getElementById('btnFullscreenGeo_Cross');
      const btnReset = document.getElementById('btnResetGeo_Cross');

      if (!canvas || !container || !wrapper) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');

      // Estado de Cámara y Traslación estilo GeoGebra
      let yaw = -0.65;       // Rotación Horizontal (Azimut)
      let pitch = 0.45;      // Inclinación Vertical (Elevación)
      let zoom = 1.0;        // Nivel de Zoom
      let panX = 0;          // Traslación Horizontal
      let panY = 0;          // Traslación Vertical
      const baseScale = 38;

      // Transformación 3D a 2D
      function project3D(xMath, yMath, zMath) {
        const cx = (canvas.width / 2) + panX;
        const cy = (canvas.height / 2 + 20) + panY;

        // 1. Rotación Yaw (Z)
        const x1 = xMath * Math.cos(yaw) - yMath * Math.sin(yaw);
        const y1 = xMath * Math.sin(yaw) + yMath * Math.cos(yaw);
        const z1 = zMath;

        // 2. Rotación Pitch (Inclinación)
        const x2 = x1;
        const y2 = y1 * Math.cos(pitch) - z1 * Math.sin(pitch);
        const z2 = y1 * Math.sin(pitch) + z1 * Math.cos(pitch);

        const currentScale = baseScale * zoom;

        return {
          px: cx + x2 * currentScale,
          py: cy - z2 * currentScale,
          zDepth: y2
        };
      }

      function drawArrow3D(p1Math, p2Math, col, widthLine = 2.5, dash = []) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z);
        const len = Math.hypot(p2.px - p1.px, p2.py - p1.py);
        if (len < 2) return;

        const angle = Math.atan2(p2.py - p1.py, p2.px - p1.px);
        const headLen = 10;

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.px, p2.py);
        ctx.lineTo(p2.px - headLen * Math.cos(angle - 0.35), p2.py - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.px - headLen * Math.cos(angle + 0.35), p2.py - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawLine3D(p1Math, p2Math, col, widthLine = 1, dash = []) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z);

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);
      }

      function drawPoint3D(pMath, col) {
        const p = project3D(pMath.x, pMath.y, pMath.z);
        ctx.beginPath();
        ctx.arc(p.px, p.py, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const O = { x: 0, y: 0, z: 0 };
        const U = { x: 2, y: 0, z: 0 };
        const V = { x: 0, y: 2, z: 0 };
        const Parall = { x: 2, y: 2, z: 0 };
        const Cross = { x: 0, y: 0, z: 4 };

        // 1. Cuadrícula de Piso (Plano XY z=0)
        ctx.beginPath();
        ctx.strokeStyle = '#e2e8f0';
        ctx.lineWidth = 1;
        for (let i = -1; i <= 5; i++) {
          const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
          ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

          const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
          ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
        }
        ctx.stroke();

        // 2. EJES COORDENADOS NEGROS SÓLIDOS
        drawArrow3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
        drawArrow3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
        drawArrow3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z

        // Etiquetas Ejes
        const pLabelX = project3D(5.5, 0, 0);
        const pLabelY = project3D(0, 5.5, 0);
        const pLabelZ = project3D(0, 0, 5.5);

        ctx.fillStyle = '#000000';
        ctx.font = 'bold 13px sans-serif';
        ctx.fillText('x', pLabelX.px, pLabelX.py);
        ctx.fillText('y', pLabelY.px, pLabelY.py);
        ctx.fillText('z', pLabelZ.px, pLabelZ.py);

        // 3. Área Sombreada del Paralelogramo de la Base (Ámbar translúcido)
        const pO = project3D(O.x, O.y, O.z);
        const pU = project3D(U.x, U.y, U.z);
        const pV = project3D(V.x, V.y, V.z);
        const pP = project3D(Parall.x, Parall.y, Parall.z);

        ctx.beginPath();
        ctx.fillStyle = 'rgba(245, 158, 11, 0.25)';
        ctx.moveTo(pO.px, pO.py);
        ctx.lineTo(pU.px, pU.py);
        ctx.lineTo(pP.px, pP.py);
        ctx.lineTo(pV.px, pV.py);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 1.3;
        ctx.stroke();

        // 4. DOS SÍMBOLOS DE ÁNGULO RECTO (90º) EN 3D
        // A. Entre Producto Cruz (Z) y Vector u (X) en el plano XZ
        const pSqX_1 = project3D(0.4, 0, 0);
        const pSqX_2 = project3D(0.4, 0, 0.4);
        const pSqX_3 = project3D(0, 0, 0.4);

        ctx.beginPath();
        ctx.strokeStyle = '#2563eb';
        ctx.lineWidth = 1.8;
        ctx.moveTo(pSqX_1.px, pSqX_1.py);
        ctx.lineTo(pSqX_2.px, pSqX_2.py);
        ctx.lineTo(pSqX_3.px, pSqX_3.py);
        ctx.stroke();

        // B. Entre Producto Cruz (Z) y Vector v (Y) en el plano YZ
        const pSqY_1 = project3D(0, 0.4, 0);
        const pSqY_2 = project3D(0, 0.4, 0.4);
        const pSqY_3 = project3D(0, 0, 0.4);

        ctx.beginPath();
        ctx.strokeStyle = '#2563eb';
        ctx.lineWidth = 1.8;
        ctx.moveTo(pSqY_1.px, pSqY_1.py);
        ctx.lineTo(pSqY_2.px, pSqY_2.py);
        ctx.lineTo(pSqY_3.px, pSqY_3.py);
        ctx.stroke();

        // 5. Vectores Principales
        drawArrow3D(O, U, '#dc2626', 3.0); // Vector u en Rojo
        drawPoint3D(U, '#b91c1c');

        drawArrow3D(O, V, '#059669', 3.0); // Vector v en Verde
        drawPoint3D(V, '#047857');

        drawArrow3D(O, Cross, '#2563eb', 3.5); // Producto Cruz u x v en Azul
        drawPoint3D(Cross, '#1d4ed8');

        drawPoint3D(O, '#000000');
      }

      // NAVEGACIÓN CON RATÓN
      let isDragging = false;
      let prevMousePos = { x: 0, y: 0 };

      canvas.addEventListener('mousedown', (e) => {
        isDragging = true;
        canvas.style.cursor = 'grabbing';
        prevMousePos = { x: e.clientX, y: e.clientY };
      });

      window.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const deltaX = e.clientX - prevMousePos.x;
        const deltaY = e.clientY - prevMousePos.y;

        yaw += deltaX * 0.008;
        pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

        prevMousePos = { x: e.clientX, y: e.clientY };
        draw();
      });

      window.addEventListener('mouseup', () => {
        isDragging = false;
        canvas.style.cursor = 'grab';
      });

      // ZOOM CON LA RUEDA DEL RATÓN (Sin Shift = Centro | Con Shift = Puntero del Ratón)
      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();
        const oldZoom = zoom;
        let newZoom = oldZoom;

        if (e.deltaY < 0) {
          newZoom = Math.min(3.5, oldZoom * 1.08);
        } else {
          newZoom = Math.max(0.3, oldZoom / 1.08);
        }

        if (e.shiftKey) {
          const rect = canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const scaleRatio = newZoom / oldZoom;
          const originX = (canvas.width / 2) + panX;
          const originY = (canvas.height / 2 + 20) + panY;

          panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
          panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2 + 20);
        }

        zoom = newZoom;
        draw();
      }, { passive: false });

      // TRASLACIÓN CON TECLAS DEL TECLADO (←, →, ↑, ↓)
      canvas.addEventListener('keydown', (e) => {
        const step = 15;
        if (e.key === 'ArrowLeft') { panX -= step; draw(); e.preventDefault(); }
        else if (e.key === 'ArrowRight') { panX += step; draw(); e.preventDefault(); }
        else if (e.key === 'ArrowUp') { panY -= step; draw(); e.preventDefault(); }
        else if (e.key === 'ArrowDown') { panY += step; draw(); e.preventDefault(); }
      });

      // VISTAS ORTOGONALES
      if (btnViewX) btnViewX.onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
      if (btnViewY) btnViewY.onclick = () => { yaw = 0; pitch = 0; draw(); };
      if (btnViewZ) btnViewZ.onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };

      if (btnReset) btnReset.onclick = () => {
        yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
      };

      // PANTALLA COMPLETA
      if (btnFullscreen) {
        btnFullscreen.onclick = () => {
          if (!document.fullscreenElement) {
            if (container.requestFullscreen) container.requestFullscreen();
            else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
          } else {
            if (document.exitFullscreen) document.exitFullscreen();
          }
        };
      }

      function updateCanvasSize() {
        if (document.fullscreenElement) {
          container.style.width = '100vw';
          container.style.height = '100vh';
          container.style.borderRadius = '0';
          container.style.padding = '16px';
          container.style.display = 'flex';
          container.style.flexDirection = 'column';
          container.style.justifyContent = 'space-between';

          const controlsHeight = 110;
          wrapper.style.width = '100%';
          wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

          canvas.width = wrapper.clientWidth;
          canvas.height = window.innerHeight - controlsHeight;
        } else {
          container.style.width = '';
          container.style.height = '';
          container.style.borderRadius = '16px';
          container.style.padding = '16px';
          container.style.display = 'inline-block';

          wrapper.style.width = '620px';
          wrapper.style.height = '420px';

          canvas.width = 620;
          canvas.height = 420;
        }
        draw();
      }

      document.addEventListener('fullscreenchange', updateCanvasSize);
      window.addEventListener('resize', updateCanvasSize);

      draw();
    }

    renderGraph();
  })();
</script>
\end{html}

