  <div id="wrapperCanvas3D_Mix" style="position: relative; width: 620px; height: 420px; margin: 0 auto; overflow: hidden; border-radius: 10px; background: #ffffff;">
    <!-- Lienzo Canvas 3D (Fondo Blanco + Ejes Negros) -->
