    <!-- Fórmulas Overlay en KaTeX (Sin \langle ni \rangle) -->
    <div style="position: absolute; top: 15px; left: 20px; pointer-events: none; color: #0f172a; font-size: 13px; text-align: left; background: rgba(255,255,255,0.92); padding: 10px 16px; border-radius: 8px; border: 1px solid #cbd5e1; box-shadow: 0 2px 8px rgba(0,0,0,0.05); z-index: 10;">
