      <div id="infoRecta3D" style="color: #d97706; font-size: 12px; font-weight: bold; margin-top: 4px;">\(\vec{x} = (3.5, 3.0, 3.5)\)</div>
    </div>

    <!-- ETIQUETAS KATEX FLOTANTES EN EL ESPACIO 3D -->
    <div id="labelP0_recta" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #0284c7; font-weight: bold; font-size: 14px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{p}\)</div>
    <div id="labelX_recta" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #d97706; font-weight: bold; font-size: 14px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{x}\)</div>
    <div id="labelD_recta" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #059669; font-weight: bold; font-size: 14px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{d}\)</div>
    <div id="labelL_recta" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #e11d48; font-weight: bold; font-size: 15px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(L\)</div>

    <!-- Leyenda de Colores (Top-Right) -->
    <div style="position: absolute; top: 15px; right: 20px; pointer-events: none; background: rgba(255,255,255,0.92); padding: 8px 12px; border-radius: 8px; border: 1px solid #cbd5e1; box-shadow: 0 2px 8px rgba(0,0,0,0.06); font-size: 11px; text-align: left; color: #0f172a;">
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #0284c7;"></span> \(\vec{p}\) (Punto Fijo)
      </div>
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #059669;"></span> \(\vec{d}\) (Vector Director)
      </div>
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #d97706;"></span> \(\vec{x}\) (Punto Genérico)
      </div>
      <div style="display: flex; align-items: center; gap: 6px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #e11d48;"></span> Recta \(L\)
      </div>
    </div>
  </div>

  <!-- PANEL DE CONTROL E INTERACCIÓN -->
  <div style="margin-top: 14px; display: flex; flex-direction: column; gap: 10px; align-items: center;">
    <!-- Control Slider para Lambda -->
    <div style="display: flex; align-items: center; gap: 12px; background: #f8fafc; padding: 8px 16px; border-radius: 8px; border: 1px solid #e2e8f0; width: 90%; justify-content: center;">
      <label for="sliderLambdaRecta" style="font-size: 13px; font-weight: 600; color: #1e293b;">Parámetro \(\lambda\):</label>
      <input type="range" id="sliderLambdaRecta" min="-1.5" max="2.5" step="0.1" value="1.0" style="width: 220px; cursor: pointer;">
      <span id="valLambdaRecta" style="font-size: 13px; font-weight: 700; color: #0284c7; min-width: 40px; text-align: left;">1.0</span>
    </div>

    <!-- Botones de Vistas Predefinidas y Pantalla Completa -->
    <div style="display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; align-items: center;">
      <button id="btnVX_recta" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje X</button>
      <button id="btnVY_recta" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Y</button>
      <button id="btnVZ_recta" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Z (Cenital)</button>
      <button id="btnReset_recta" style="background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">Restablecer Vista</button>
      <button id="btnFS_recta" style="background: #0284c7; color: #ffffff; border: 1px solid #0369a1; padding: 5px 12px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600; display: flex; align-items: center; gap: 5px;">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"/></svg>
        Pantalla Completa
      </button>
    </div>

    <div style="font-size: 11px; color: #64748b; line-height: 1.4;">
      💡 <b>Arrastrar ratón:</b> Rotar vista 3D &nbsp;|&nbsp; <b>Rueda:</b> Zoom al centro &nbsp;|&nbsp; <b>Shift + Rueda:</b> Zoom al puntero &nbsp;|&nbsp; <b>Flechas:</b> Desplazar
    </div>
