    <div id="labelL2_orto" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #059669; font-weight: bold; font-size: 14px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(L_2\)</div>
    <div id="labelD1_orto" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #0284c7; font-weight: bold; font-size: 13px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{d}_1\)</div>
    <div id="labelD2_orto" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #059669; font-weight: bold; font-size: 13px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{d}_2\)</div>
    <div id="labelP_orto" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #e11d48; font-weight: bold; font-size: 14px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec p\)</div>

    <!-- Leyenda de Colores (Top-Right) -->
    <div style="position: absolute; top: 15px; right: 20px; pointer-events: none; background: rgba(255,255,255,0.92); padding: 8px 12px; border-radius: 8px; border: 1px solid #cbd5e1; box-shadow: 0 2px 8px rgba(0,0,0,0.06); font-size: 11px; text-align: left; color: #0f172a;">
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #0284c7;"></span> Recta \(L_1: \vec{d}_1 = (2,0,0)\)
      </div>
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #059669;"></span> Recta \(L_2: \vec{d}_2 = (0,2,0)\)
      </div>
      <div style="display: flex; align-items: center; gap: 6px;">
        <span style="display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: #e11d48;"></span> Punto Intersección \(\vec p\)
