  <!-- PANEL DE CONTROL E INTERACCIÓN -->
  <div style="margin-top: 14px; display: flex; flex-direction: column; gap: 10px; align-items: center;">
    <!-- Control Slider e Intersección -->
    <div style="display: flex; align-items: center; gap: 12px; background: #f8fafc; padding: 8px 16px; border-radius: 8px; border: 1px solid #e2e8f0; width: 92%; justify-content: center; flex-wrap: wrap;">
      <label for="sliderOffsetH" style="font-size: 13px; font-weight: 600; color: #1e293b;">Separación Vertical \(h\):</label>
      <input type="range" id="sliderOffsetH" min="0.0" max="2.5" step="0.1" value="0.0" style="width: 180px; cursor: pointer;">
      <span id="valOffsetH" style="font-size: 13px; font-weight: 700; color: #0284c7; min-width: 35px; text-align: left;">0.0</span>

      <button id="btnToggleState_orto" style="background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; padding: 4px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">
        ⚡ Conmutar Estado
      </button>
    </div>

    <!-- Botones de Vistas Predefinidas y Pantalla Completa -->
    <div style="display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; align-items: center;">
      <button id="btnVX_orto" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje X</button>
      <button id="btnVY_orto" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Y</button>
      <button id="btnVZ_orto" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Z</button>
      <button id="btnReset_orto" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">Restablecer Vista</button>
      <button id="btnFS_orto" style="background: #0284c7; color: #ffffff; border: 1px solid #0369a1; padding: 5px 12px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600; display: flex; align-items: center; gap: 5px;">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"/></svg>
        Pantalla Completa
      </button>
