    <div id="labelD1_sec" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #0284c7; font-weight: bold; font-size: 13px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{d}_1\)</div>
    <div id="labelD2_sec" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #059669; font-weight: bold; font-size: 13px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(\vec{d}_2\)</div>
    <div id="labelP_sec" style="position: absolute; top: 0; left: 0; pointer-events: none; color: #e11d48; font-weight: bold; font-size: 14px; text-shadow: 0 0 5px #ffffff, 0 0 8px #ffffff; transform: translate(-50%, -100%); transition: left 0.05s ease-out, top 0.05s ease-out;">\(P\)</div>

    <!-- Leyenda de Colores (Top-Right) -->
    <div style="position: absolute; top: 15px; right: 20px; pointer-events: none; background: rgba(255,255,255,0.92); padding: 8px 12px; border-radius: 8px; border: 1px solid #cbd5e1; box-shadow: 0 2px 8px rgba(0,0,0,0.06); font-size: 11px; text-align: left; color: #0f172a;">
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #0284c7;"></span> Recta \(L_1, \vec{d}_1 = (2,1,0)\)
      </div>
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="display: inline-block; width: 12px; height: 3px; background: #059669;"></span> Recta \(L_2,  \vec{d}_2 = (1,2,1)\)
      </div>
      <div style="display: flex; align-items: center; gap: 6px;">
        <span style="display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: #e11d48;"></span> Punto Intersección \(P\)
      </div>
    </div>
  </div>

  <!-- PANEL DE CONTROL E INTERACCIÓN -->
  <div style="margin-top: 14px; display: flex; flex-direction: column; gap: 10px; align-items: center;">
    <!-- Control Slider e Intersección -->
    <div style="display: flex; align-items: center; gap: 12px; background: #f8fafc; padding: 8px 16px; border-radius: 8px; border: 1px solid #e2e8f0; width: 92%; justify-content: center; flex-wrap: wrap;">
      <label for="sliderDesplazamiento" style="font-size: 13px; font-weight: 600; color: #1e293b;">Separación Vertical \(h\):</label>
      <input type="range" id="sliderDesplazamiento" min="0.0" max="2.5" step="0.1" value="0.0" style="width: 180px; cursor: pointer;">
      <span id="valDesplazamiento" style="font-size: 13px; font-weight: 700; color: #0284c7; min-width: 35px; text-align: left;">0.0</span>

      <button id="btnToggleSec_orto" style="background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; padding: 4px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">
        ⚡ Conmutar Estado
      </button>
    </div>

    <!-- Botones de Vistas Predefinidas y Pantalla Completa -->
    <div style="display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; align-items: center;">
      <button id="btnVX_sec" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje X</button>
      <button id="btnVY_sec" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Y</button>
      <button id="btnVZ_sec" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Z (Cenital)</button>
      <button id="btnReset_sec" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">Restablecer Vista</button>
      <button id="btnFS_sec" style="background: #0284c7; color: #ffffff; border: 1px solid #0369a1; padding: 5px 12px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600; display: flex; align-items: center; gap: 5px;">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"/></svg>
        Pantalla Completa
      </button>
    </div>

    <div style="font-size: 11px; color: #64748b; line-height: 1.4;">
      💡 <b>Arrastrar ratón:</b> Rotar vista 3D &nbsp;|&nbsp; <b>Rueda:</b> Zoom al centro &nbsp;|&nbsp; <b>Shift + Rueda:</b> Zoom al puntero &nbsp;|&nbsp; <b>Flechas:</b> Desplazar
    </div>
  </div>

</div>

<script>
(function() {
  const container = document.getElementById('containerSecantes3D');
  const wrapper = document.getElementById('wrapperSecantes3D');
  const canvas = document.getElementById('canvasSecantes3D');
  const ctx = canvas.getContext('2d');
  const sliderH = document.getElementById('sliderDesplazamiento');
  const valH = document.getElementById('valDesplazamiento');
  const infoSecantes = document.getElementById('infoSecantes3D');

  // Etiquetas KaTeX flotantes
  const lblD1 = document.getElementById('labelD1_sec');
  const lblD2 = document.getElementById('labelD2_sec');
  const lblL1 = document.getElementById('labelL1_sec');
  const lblL2 = document.getElementById('labelL2_sec');
  const lblP  = document.getElementById('labelP_sec');

  let offsetH = parseFloat(sliderH.value);

  // Cámara (Estándar 1 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  // Dibujo de línea 3D
  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }

  // Dibujo de vector 3D con punta de flecha
  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // Dibujo del punto 3D
  function drawPoint3D(pt, color, radius = 4) {
    const p = project3D(pt.x, pt.y, pt.z);
    ctx.save();
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.arc(p.px, p.py, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  // Rejilla del plano z = 0 (Estándar 1)
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -1; i <= 5; i++) {
      const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

      const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }

  // Ejes Coordenados 3D (Estándar 1: Negros Sólidos)
  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);
  }

  // Función Principal de Renderizado
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();

    // Geometría de las Rectas L1 y L2 (No Paralelas: d1 x d2 != 0)
    const P1_base = { x: 1, y: 1, z: 2 };
    const P2_base = { x: 1, y: 1, z: 2 + offsetH };

    const D1 = { x: 2, y: 1, z: 0 };
    const D2 = { x: 1, y: 2, z: 1 };

    const L1_start = { x: 1 - 2 * D1.x, y: 1 - 2 * D1.y, z: 2 };
    const L1_end   = { x: 1 + 1.8 * D1.x, y: 1 + 1.8 * D1.y, z: 2 };

    const L2_start = { x: 1 - 1.8 * D2.x, y: 1 - 1.8 * D2.y, z: 2 + offsetH - 1.8 * D2.z };
    const L2_end   = { x: 1 + 1.8 * D2.x, y: 1 + 1.8 * D2.y, z: 2 + offsetH + 1.8 * D2.z };

    // Dibujar Rectas Principales L1 y L2
    drawLine3D(L1_start, L1_end, '#0284c7', 2.2);
    drawLine3D(L2_start, L2_end, '#059669', 2.2);

    // Dibujar Vectores Directores d1 y d2
    const D1_end = { x: P1_base.x + D1.x, y: P1_base.y + D1.y, z: P1_base.z + D1.z };
    const D2_end = { x: P2_base.x + D2.x, y: P2_base.y + D2.y, z: P2_base.z + D2.z };

    drawVector3D(P1_base, D1_end, '#0284c7', 2.8);
    drawVector3D(P2_base, D2_end, '#059669', 2.8);

    // Evaluación del Estado (Secantes vs Alabeadas)
    if (Math.abs(offsetH) < 0.05) {
      // ESTADO: RECTAS SECANTES (Se intersectan en P)
      drawPoint3D(P1_base, '#e11d48', 6);

      if (lblP) {
        lblP.style.display = 'block';
        const pP = project3D(P1_base.x, P1_base.y, P1_base.z);
        lblP.style.left = pP.px + 'px';
        lblP.style.top  = (pP.py - 16) + 'px';
      }
    } else {
      // ESTADO: RECTAS ALABEADAS / CRUZADAS (Planos Paralelos Distintos)
      drawLine3D(P1_base, P2_base, '#94a3b8', 1.8, [4, 4]);
      drawPoint3D(P1_base, '#0284c7', 4.5);
      drawPoint3D(P2_base, '#059669', 4.5);

      if (lblP) lblP.style.display = 'none';
    }

    // Actualizar Posición de Etiquetas KaTeX Flotantes
    const posD1 = project3D(P1_base.x + D1.x * 0.5, P1_base.y + D1.y * 0.5, P1_base.z);
    const posD2 = project3D(P2_base.x + D2.x * 0.5, P2_base.y + D2.y * 0.5, P2_base.z + D2.z * 0.5);
    const posL1 = project3D(L1_end.x, L1_end.y, L1_end.z);
    const posL2 = project3D(L2_end.x, L2_end.y, L2_end.z);

    if (lblD1) { lblD1.style.left = posD1.px + 'px'; lblD1.style.top = (posD1.py - 12) + 'px'; }
    if (lblD2) { lblD2.style.left = posD2.px + 'px'; lblD2.style.top = (posD2.py - 12) + 'px'; }
    if (lblL1) { lblL1.style.left = posL1.px + 'px'; lblL1.style.top = (posL1.py - 10) + 'px'; }
    if (lblL2) { lblL2.style.left = posL2.px + 'px'; lblL2.style.top = (posL2.py - 10) + 'px'; }

    // Actualizar Panel de Información KaTeX Overlay
    if (infoSecantes) {
      if (Math.abs(offsetH) < 0.05) {
        infoSecantes.innerHTML = `
          <div style="color: #0284c7; font-weight: 700; margin-bottom: 2px;">Rectas Secantes</div>
          <div style="color: #334155; font-size: 12px;">\\(\\vec{d}_1 \\times \\vec{d}_2 \\neq \\vec{0}\\) \\(\\quad\\) (Sistema Compatible Determinado)</div>
          <div style="color: #64748b; font-size: 11px; margin-top: 2px;">Punto único de intersección: \\(P = (1, 1, 2)\\)</div>
        `;
      } else {
        infoSecantes.innerHTML = `
          <div style="color: #d97706; font-weight: 700; margin-bottom: 2px;">Rectas Alabeadas</div>
          <div style="color: #334155; font-size: 12px;">\\(\\vec{d}_1 \\nparallel \\vec{d}_2\\) \\(\\quad\\) (Sistema Incompatible)</div>
          <div style="color: #64748b; font-size: 11px; margin-top: 2px;">Separación entre planos paralelos: \\(h = ${offsetH.toFixed(2)}\\)</div>
        `;
      }

      if (window.renderMathInElement) {
        window.renderMathInElement(infoSecantes, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Eventos de Slider y Botón de Conmutación
  sliderH.addEventListener('input', (e) => {
    offsetH = parseFloat(e.target.value);
    valH.textContent = offsetH.toFixed(1);
    draw();
  });

  document.getElementById('btnToggleSec_orto').onclick = () => {
    offsetH = (Math.abs(offsetH) < 0.05) ? 1.5 : 0.0;
    sliderH.value = offsetH;
    valH.textContent = offsetH.toFixed(1);
    draw();
  };

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con la Rueda del Ratón
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas Teclado
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderH) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_sec').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_sec').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_sec').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_sec').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_sec').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 120;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
\end{html}

