  const D = { x: 2.0, y: 1.0, z: 1.0 };      // Vector director d
  // Cálculo del lambda* óptimo: (q - p) . d / ||d||^2
  const normDSq = D.x * D.x + D.y * D.y + D.z * D.z; // 4 + 1 + 1 = 6
  const dotQP_D = (Q.x - P0.x) * D.x + (Q.y - P0.y) * D.y + (Q.z - P0.z) * D.z; // 0(2) + 3(1) + 2(1) = 5
  const lambdaOpt = dotQP_D / normDSq; // 5/6 ≈ 0.8333
