  }
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawGrid3D();
    drawAxes3D();
    // Punto genérico P(lambda) sobre la recta L
    const P_curr = {
      x: P0.x + lambda * D.x,
      y: P0.y + lambda * D.y,
      z: P0.z + lambda * D.z
    };
    // Tramo de la Recta L
    const L_start = { x: P0.x - 1.0 * D.x, y: P0.y - 1.0 * D.y, z: P0.z - 1.0 * D.z };
    const L_end   = { x: P0.x + 2.5 * D.x, y: P0.y + 2.5 * D.y, z: P0.z + 2.5 * D.z };
    drawLine3D(L_start, L_end, '#0284c7', 2.2);
    // Vector Director d aplicado en P0
    const D_end = { x: P0.x + D.x, y: P0.y + D.y, z: P0.z + D.z };
    drawVector3D(P0, D_end, '#059669', 2.5);
    // Vector w(lambda) = q - P(lambda) entre el punto genérico y q
    drawLine3D(P_curr, Q, '#8b5cf6', 2.0, [5, 4]);
    // Punto Exterior Q
    drawPoint3D(Q, '#8b5cf6', 6);
    // Punto Inicial P0
    drawPoint3D(P0, '#0284c7', 4.5);
    // Distancia actual d(lambda)
    const distCurr = Math.hypot(Q.x - P_curr.x, Q.y - P_curr.y, Q.z - P_curr.z);
    const isOptimal = Math.abs(lambda - lambdaOpt) < 0.03;
    if (isOptimal) {
