<script>
  (function() {
    let animId = null;
    let animProgress = 1; // 0 = en origen, 1 = en P(3,1)
    let isMoving = false;

    function renderGraph() {
      const canvas = document.getElementById('canvasVectoresLibres');
      const btn = document.getElementById('btnTranslacionVector');
      if (!canvas || !btn) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;

      const sc = 45; // Escala: 1 unidad = 45px
      const cx = 55; // Origen X
      const cy = 300; // Origen Y

      const pt = (x, y) => ({ x: cx + x * sc, y: cy - y * sc });

      // Dibuja flechas con punta estilizada
      const drawArrow = (x1, y1, x2, y2, col, widthLine = 2.5, dash = []) => {
        const p1 = pt(x1, y1), p2 = pt(x2, y2);
        const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        const headLen = 10;

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        // Punta de la flecha
        ctx.beginPath();
        ctx.moveTo(p2.x, p2.y);
        ctx.lineTo(p2.x - headLen * Math.cos(angle - 0.35), p2.y - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.x - headLen * Math.cos(angle + 0.35), p2.y - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      };

      const drawPoint = (x, y, col = '#64748b') => {
        const p = pt(x, y);
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      };

      function draw() {
        ctx.clearRect(0, 0, width, height);

        // 1. Cuadrícula tenue
        ctx.beginPath();
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 9; i++) {
          ctx.moveTo(pt(i, 0).x, 0); ctx.lineTo(pt(i, 0).x, height);
          ctx.moveTo(0, pt(0, i).y); ctx.lineTo(width, pt(0, i).y);
        }
        ctx.stroke();

        // 2. Ejes Cartesiano X e Y
        drawArrow(0, 0, 9.2, 0, '#64748b', 1.5);
        drawArrow(0, 0, 0, 6.2, '#64748b', 1.5);

        // 3. Proyecciones triangulares de los componentes (3, 4)
        // Referencias Vector Posición (Azul)
        ctx.beginPath();
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = '#93c5fd';
        ctx.lineWidth = 1.5;
        ctx.moveTo(pt(0, 0).x, pt(0, 0).y);
        ctx.lineTo(pt(3, 0).x, pt(3, 0).y);
        ctx.lineTo(pt(3, 4).x, pt(3, 4).y);
        ctx.stroke();

        // Referencias Vector Libre Fijo en P(3,1) (Verde)
        ctx.beginPath();
        ctx.strokeStyle = '#a7f3d0';
        ctx.moveTo(pt(3, 1).x, pt(3, 1).y);
        ctx.lineTo(pt(6, 1).x, pt(6, 1).y);
        ctx.lineTo(pt(6, 5).x, pt(6, 5).y);
        ctx.stroke();
        ctx.setLineDash([]);

        // 4. Vector de Posición Fijo en Origen (Azul)
        drawArrow(0, 0, 3, 4, '#2563eb', 3);
        drawPoint(0, 0, '#475569');
        drawPoint(3, 4, '#1d4ed8');

        // 5. Vector Libre Animado (Verde) que se traslada de (0,0) a P(3,1)
        const curStartX = animProgress * 3;
        const curStartY = animProgress * 1;
        const curEndX = curStartX + 3;
        const curEndY = curStartY + 4;

        // Trayectoria de la traslación (punteada morada)
        if (animProgress > 0 && animProgress < 1) {
          ctx.beginPath();
          ctx.setLineDash([3, 3]);
          ctx.strokeStyle = '#c084fc';
          ctx.lineWidth = 1.2;
          ctx.moveTo(pt(0, 0).x, pt(0, 0).y);
          ctx.lineTo(pt(curStartX, curStartY).x, pt(curStartX, curStartY).y);
          ctx.stroke();
          ctx.setLineDash([]);
        }

        drawArrow(curStartX, curStartY, curEndX, curEndY, '#059669', 3);
        drawPoint(curStartX, curStartY, '#047857');
        drawPoint(curEndX, curEndY, '#047857');
      }

      // Animación suave de traslación
      function animateTranslation() {
        if (isMoving) {
          animProgress += 0.02;
          if (animProgress >= 1) {
            animProgress = 1;
            isMoving = false;
            btn.innerHTML = '🔄 Reanimar Traslación a P(3,1)';
          }
          draw();
          if (isMoving) requestAnimationFrame(animateTranslation);
        }
      }

      btn.onclick = () => {
        if (isMoving) return;
        animProgress = 0;
        isMoving = true;
        btn.innerHTML = '⏳ Trasladando Vector...';
        animateTranslation();
      };

      draw();
    }

    renderGraph();
  })();
</script>
