<script>
  (function() {
    let mode = 'desplazamiento'; // 'desplazamiento' o 'inverso'

    function renderGraph() {
      const canvas = document.getElementById('canvasRestaR2');
      const btn = document.getElementById('btnModoResta');
      const lblResta = document.getElementById('lblRestaCalculo');
      if (!canvas || !btn || !lblResta) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;

      const sc = 45; // 1 unidad = 45px
      const cx = 55; // Origen X
      const cy = 300; // Origen Y

      const pt = (x, y) => ({ x: cx + x * sc, y: cy - y * sc });

      function drawArrow(x1, y1, x2, y2, col, widthLine = 2.5, dash = []) {
        const p1 = pt(x1, y1), p2 = pt(x2, y2);
        const len = Math.hypot(p2.x - p1.x, p2.y - p1.y);
        if (len < 2) return;

        const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        const headLen = 10;

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.x, p2.y);
        ctx.lineTo(p2.x - headLen * Math.cos(angle - 0.35), p2.y - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.x - headLen * Math.cos(angle + 0.35), p2.y - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawPoint(x, y, col = '#64748b') {
        const p = pt(x, y);
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        ctx.clearRect(0, 0, width, height);

        // 1. Cuadrícula tenue
        ctx.beginPath();
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 9; i++) {
          ctx.moveTo(pt(i, 0).x, 0); ctx.lineTo(pt(i, 0).x, height);
          ctx.moveTo(0, pt(0, i).y); ctx.lineTo(width, pt(0, i).y);
        }
        ctx.stroke();

        // 2. Ejes Cartesiano X e Y
        drawArrow(0, 0, 9.6, 0, '#64748b', 1.5);
        drawArrow(0, 0, 0, 6.2, '#64748b', 1.5);

        // 3. Vectores de Posición A(1,2) y B(6,2)
        drawArrow(0, 0, 1, 2, '#3b82f6', 2.5);
        drawPoint(1, 2, '#2563eb');

        drawArrow(0, 0, 6, 2, '#1d4ed8', 2.5);
        drawPoint(6, 2, '#1e40af');
        drawPoint(0, 0, '#475569');

        if (mode === 'desplazamiento') {
          // Línea de referencia horizontal
          ctx.beginPath();
          ctx.setLineDash([4, 4]);
          ctx.strokeStyle = '#cbd5e1';
          ctx.lineWidth = 1.2;
          ctx.moveTo(pt(1, 2).x, pt(1, 2).y);
          ctx.lineTo(pt(6, 2).x, pt(6, 2).y);
          ctx.stroke();
          ctx.setLineDash([]);

          // Vector Resta directamente desde A(1,2) hasta B(6,2)
          drawArrow(1, 2, 6, 2, '#dc2626', 3.2);

          lblResta.style.top = '185px';
          lblResta.style.left = '200px';
        } else {
          // Modo Suma con el Inverso: B + (-A)
          // Dibujar el inverso -A (-1, -2) partiendo desde la cabeza de B(6,2) hasta (5,0)
          drawArrow(6, 2, 5, 0, '#f87171', 2.5, [4, 4]);
          drawPoint(5, 0, '#dc2626');

          // Vector Posición de la resta en el Origen (0,0) -> (5,0)
          drawArrow(0, 0, 5, 0, '#dc2626', 3.2);

          lblResta.style.top = '275px';
          lblResta.style.left = '160px';
        }
      }

      btn.onclick = () => {
        if (mode === 'desplazamiento') {
          mode = 'inverso';
          btn.innerHTML = '🔄 Mostrar Vector Desplazamiento A ➔ B';
        } else {
          mode = 'desplazamiento';
          btn.innerHTML = '🔄 Mostrar Suma con el Inverso: \\(\\vec{B} + (-\\vec{A})\\)';
          if (window.renderMathInElement) renderMathInElement(btn);
        }
        draw();
      };

      draw();
    }

    renderGraph();
  })();
</script>
