        ctx.fillStyle = 'rgba(59, 130, 246, 0.08)';
        ctx.moveTo(pt(0, 0).x, pt(0, 0).y);
        ctx.lineTo(pt(vx, 0).x, pt(vx, 0).y);
        ctx.lineTo(pt(vx, vy).x, pt(vx, vy).y);
        ctx.closePath();
        ctx.fill();

        // 4. Marca de Ángulo Recto (90º) en (vx, 0)
