        const sqSize = 12;
        ctx.beginPath();
        ctx.strokeStyle = '#64748b';
        ctx.lineWidth = 1.2;
        ctx.moveTo(pSquare.x - sqSize, pSquare.y);
        ctx.lineTo(pSquare.x - sqSize, pSquare.y - sqSize);
        ctx.lineTo(pSquare.x, pSquare.y - sqSize);
        ctx.stroke();

        // 5. Catetos del Triángulo Rectángulo (Punteados)
        // Cateto horizontal vx
        ctx.beginPath();
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 2.5;
        ctx.moveTo(pt(0, 0).x, pt(0, 0).y);
        ctx.lineTo(pt(vx, 0).x, pt(vx, 0).y);
        ctx.stroke();

        // Cateto vertical vy
