        ctx.strokeStyle = '#059669';
        ctx.lineWidth = 2.5;
        ctx.moveTo(pt(vx, 0).x, pt(vx, 0).y);
        ctx.lineTo(pt(vx, vy).x, pt(vx, vy).y);
        ctx.stroke();

        // 6. Vector Principal v (Hipotenusa) [Azul Cobalt]
        drawArrow(0, 0, vx, vy, '#2563eb', 3.2);
        drawPoint(0, 0, '#475569');
        drawPoint(vx, vy, '#1d4ed8');

        // Etiquetas de los catetos en el lienzo
        ctx.fillStyle = '#b45309';
        ctx.font = 'bold 12px sans-serif';
        const pMidX = pt(vx / 2, 0);
        ctx.fillText(`vₓ = ${vx}`, pMidX.x - 12, pMidX.y + 18);

        ctx.fillStyle = '#047857';
        const pMidY = pt(vx, vy / 2);
        ctx.fillText(`vᵧ = ${vy}`, pMidY.x + 8, pMidY.y + 4);
      }

      rangeVx.oninput = draw;
      rangeVy.oninput = draw;

