<script>
  (function() {
    function renderGraph() {
      const container = document.getElementById('containerGeo3D_Mix');
      const wrapper = document.getElementById('wrapperCanvas3D_Mix');
      const canvas = document.getElementById('canvasGeoGebra3D_Mix');

      const btnViewX = document.getElementById('btnViewX_Mix');
      const btnViewY = document.getElementById('btnViewY_Mix');
      const btnViewZ = document.getElementById('btnViewZ_Mix');
      const btnFullscreen = document.getElementById('btnFullscreenGeo_Mix');
      const btnReset = document.getElementById('btnResetGeo_Mix');

      if (!canvas || !container || !wrapper) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');

      // Estado de Cámara y Traslación estilo GeoGebra
      let yaw = -0.75;       // Rotación Horizontal (Azimut)
      let pitch = 0.40;      // Inclinación Vertical (Elevación)
      let zoom = 1.0;        // Nivel de Zoom
      let panX = 0;          // Traslación Horizontal
      let panY = 0;          // Traslación Vertical
      const baseScale = 36;

      // Transformación 3D a 2D
      function project3D(xMath, yMath, zMath) {
        const cx = (canvas.width / 2) + panX;
        const cy = (canvas.height / 2 + 35) + panY;

        // 1. Rotación Yaw (Z)
        const x1 = xMath * Math.cos(yaw) - yMath * Math.sin(yaw);
        const y1 = xMath * Math.sin(yaw) + yMath * Math.cos(yaw);
        const z1 = zMath;

        // 2. Rotación Pitch (Inclinación)
        const x2 = x1;
        const y2 = y1 * Math.cos(pitch) - z1 * Math.sin(pitch);
        const z2 = y1 * Math.sin(pitch) + z1 * Math.cos(pitch);

        const currentScale = baseScale * zoom;

        return {
          px: cx + x2 * currentScale,
          py: cy - z2 * currentScale,
          zDepth: y2
        };
      }

      function drawArrow3D(p1Math, p2Math, col, widthLine = 2.5, dash = []) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z);
        const len = Math.hypot(p2.px - p1.px, p2.py - p1.py);
        if (len < 2) return;

        const angle = Math.atan2(p2.py - p1.py, p2.px - p1.px);
        const headLen = 10;

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.px, p2.py);
        ctx.lineTo(p2.px - headLen * Math.cos(angle - 0.35), p2.py - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.px - headLen * Math.cos(angle + 0.35), p2.py - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawLine3D(p1Math, p2Math, col, widthLine = 1, dash = []) {
        const p1 = project3D(p1Math.x, p1Math.y, p1Math.z);
        const p2 = project3D(p2Math.x, p2Math.y, p2Math.z);

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.px, p1.py);
        ctx.lineTo(p2.px, p2.py);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);
      }

      function drawPoint3D(pMath, col) {
        const p = project3D(pMath.x, pMath.y, pMath.z);
        ctx.beginPath();
        ctx.arc(p.px, p.py, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Coordenadas de los Vectores del Paralelepípedo
        const O = { x: 0, y: 0, z: 0 };
        const V = { x: 3, y: 0, z: 0 };
        const W = { x: 1, y: 2.5, z: 0 };
        const VW = { x: 4, y: 2.5, z: 0 };

        const U = { x: 0, y: 3, z: 4 };
        const UV = { x: 3, y: 3, z: 4 };
        const UW = { x: 1, y: 5.5, z: 4 };
        const UVW = { x: 4, y: 5.5, z: 4 };

        const N = { x: 0, y: 0, z: 7.5 }; // Normal v x w
        const H = { x: 0, y: 0, z: 4 };   // Altura proyectada

        // 1. Cuadrícula de Piso (Plano XY z=0)
        ctx.beginPath();
        ctx.strokeStyle = '#e2e8f0';
        ctx.lineWidth = 1;
        for (let i = -1; i <= 6; i++) {
          const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 6, 0);
          ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

          const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
          ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
        }
        ctx.stroke();

        // 2. EJES COORDENADOS NEGROS SÓLIDOS (Estilo GeoGebra 3D)
        drawArrow3D(O, { x: 5.5, y: 0, z: 0 }, '#000000', 2.0); // Eje X
        drawArrow3D(O, { x: 0, y: 6.5, z: 0 }, '#000000', 2.0); // Eje Y
        drawArrow3D(O, { x: 0, y: 0, z: 8.0 }, '#000000', 2.0); // Eje Z

        // Etiquetas Ejes
        const pLabelX = project3D(5.8, 0, 0);
        const pLabelY = project3D(0, 6.8, 0);
        const pLabelZ = project3D(0, 0, 8.3);

        ctx.fillStyle = '#000000';
        ctx.font = 'bold 13px sans-serif';
        ctx.fillText('x', pLabelX.px, pLabelX.py);
        ctx.fillText('y', pLabelY.px, pLabelY.py);
        ctx.fillText('z', pLabelZ.px, pLabelZ.py);

        // 3. Caras Sombreadas del Paralelepípedo
        const pO = project3D(O.x, O.y, O.z);
        const pV = project3D(V.x, V.y, V.z);
        const pW = project3D(W.x, W.y, W.z);
        const pVW = project3D(VW.x, VW.y, VW.z);

        const pU = project3D(U.x, U.y, U.z);
        const pUV = project3D(UV.x, UV.y, UV.z);
        const pUW = project3D(UW.x, UW.y, UW.z);
        const pUVW = project3D(UVW.x, UVW.y, UVW.z);

        // Base (Ámbar translúcido)
        ctx.beginPath();
        ctx.fillStyle = 'rgba(245, 158, 11, 0.25)';
        ctx.moveTo(pO.px, pO.py); ctx.lineTo(pV.px, pV.py);
        ctx.lineTo(pVW.px, pVW.py); ctx.lineTo(pW.px, pW.py);
        ctx.closePath();
        ctx.fill();

        // Cuerpo (Azul/Púrpura translúcido)
        ctx.beginPath();
        ctx.fillStyle = 'rgba(37, 99, 235, 0.08)';
        ctx.moveTo(pU.px, pU.py); ctx.lineTo(pUV.px, pUV.py);
        ctx.lineTo(pUVW.px, pUVW.py); ctx.lineTo(pUW.px, pUW.py);
        ctx.closePath();
        ctx.fill();

        // 4. Aristas del Paralelepípedo
        drawLine3D(V, VW, '#cbd5e1', 1.3);
        drawLine3D(W, VW, '#cbd5e1', 1.3);

        drawLine3D(U, UV, '#94a3b8', 1.3, [4, 4]);
        drawLine3D(U, UW, '#94a3b8', 1.3, [4, 4]);
        drawLine3D(UV, UVW, '#94a3b8', 1.3, [4, 4]);
        drawLine3D(UW, UVW, '#94a3b8', 1.3, [4, 4]);

        drawLine3D(V, UV, '#94a3b8', 1.3, [4, 4]);
        drawLine3D(W, UW, '#94a3b8', 1.3, [4, 4]);
        drawLine3D(VW, UVW, '#94a3b8', 1.3, [4, 4]);

        // 5. Línea de Proyección de la Altura h
        drawLine3D(U, H, '#7c3aed', 1.8, [4, 4]);
        drawLine3D(O, H, '#7c3aed', 3.0); // Tramo de la Altura

        // 6. Vectores Principales
        drawArrow3D(O, V, '#dc2626', 3.0); // Base v (Rojo)
        drawPoint3D(V, '#b91c1c');

        drawArrow3D(O, W, '#059669', 3.0); // Base w (Verde)
        drawPoint3D(W, '#047857');

        drawArrow3D(O, U, '#7c3aed', 3.2); // Inclinado u (Morado)
        drawPoint3D(U, '#6d28d9');

        drawArrow3D(O, N, '#2563eb', 3.0); // Normal (v x w) (Azul)
        drawPoint3D(N, '#1d4ed8');

        drawPoint3D(O, '#000000');
      }

      // NAVEGACIÓN CON RATÓN
      let isDragging = false;
      let prevMousePos = { x: 0, y: 0 };

      canvas.addEventListener('mousedown', (e) => {
        isDragging = true;
        canvas.style.cursor = 'grabbing';
        prevMousePos = { x: e.clientX, y: e.clientY };
      });

      window.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const deltaX = e.clientX - prevMousePos.x;
        const deltaY = e.clientY - prevMousePos.y;

        yaw += deltaX * 0.008;
        pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

        prevMousePos = { x: e.clientX, y: e.clientY };
        draw();
      });

      window.addEventListener('mouseup', () => {
        isDragging = false;
        canvas.style.cursor = 'grab';
      });

      // ZOOM CON LA RUEDA DEL RATÓN (Sin Shift = Centro | Con Shift = Puntero del Ratón)
      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();
        const oldZoom = zoom;
        let newZoom = oldZoom;

        if (e.deltaY < 0) {
          newZoom = Math.min(3.5, oldZoom * 1.08);
        } else {
          newZoom = Math.max(0.3, oldZoom / 1.08);
        }

        if (e.shiftKey) {
          const rect = canvas.getBoundingClientRect();
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const scaleRatio = newZoom / oldZoom;
          const originX = (canvas.width / 2) + panX;
          const originY = (canvas.height / 2 + 35) + panY;

          panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
          panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2 + 35);
        }

        zoom = newZoom;
        draw();
      }, { passive: false });

      // TRASLACIÓN CON TECLAS DEL TECLADO (←, →, ↑, ↓)
      canvas.addEventListener('keydown', (e) => {
        const step = 15;
        if (e.key === 'ArrowLeft') { panX -= step; draw(); e.preventDefault(); }
        else if (e.key === 'ArrowRight') { panX += step; draw(); e.preventDefault(); }
        else if (e.key === 'ArrowUp') { panY -= step; draw(); e.preventDefault(); }
        else if (e.key === 'ArrowDown') { panY += step; draw(); e.preventDefault(); }
      });

      // VISTAS ORTOGONALES
      if (btnViewX) btnViewX.onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
      if (btnViewY) btnViewY.onclick = () => { yaw = 0; pitch = 0; draw(); };
      if (btnViewZ) btnViewZ.onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };

      if (btnReset) btnReset.onclick = () => {
        yaw = -0.75; pitch = 0.40; zoom = 1.0; panX = 0; panY = 0; draw();
      };

      // PANTALLA COMPLETA
      if (btnFullscreen) {
        btnFullscreen.onclick = () => {
          if (!document.fullscreenElement) {
            if (container.requestFullscreen) container.requestFullscreen();
            else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
          } else {
            if (document.exitFullscreen) document.exitFullscreen();
          }
        };
      }

      function updateCanvasSize() {
        if (document.fullscreenElement) {
          container.style.width = '100vw';
          container.style.height = '100vh';
          container.style.borderRadius = '0';
          container.style.padding = '16px';
          container.style.display = 'flex';
          container.style.flexDirection = 'column';
          container.style.justifyContent = 'space-between';

          const controlsHeight = 110;
          wrapper.style.width = '100%';
          wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

          canvas.width = wrapper.clientWidth;
          canvas.height = window.innerHeight - controlsHeight;
        } else {
          container.style.width = '';
          container.style.height = '';
          container.style.borderRadius = '16px';
          container.style.padding = '16px';
          container.style.display = 'inline-block';

          wrapper.style.width = '620px';
          wrapper.style.height = '420px';

          canvas.width = 620;
          canvas.height = 420;
        }
        draw();
      }

      document.addEventListener('fullscreenchange', updateCanvasSize);
      window.addEventListener('resize', updateCanvasSize);

      draw();
    }

    renderGraph();
  })();
</script>
\end{html}
\end{card}

chapters.motivacion:
\begin{card}
<p><strong>El Salto Mental: Del Plano $\mathbb{R}^2$ al Espacio $\mathbb{R}^3$</strong></p>

<p>En el plano $\mathbb{R}^2$, estabas acostumbrado a describir una recta mediante una sola ecuación lineal con una pendiente escalar:</p>
$$ax + by = c \quad \text{o bien} \quad y = mx + b$$

<p>Sin embargo, al dar el salto al espacio tridimensional $\mathbb{R}^3$, ocurre un cambio conceptual fundamental: <strong>una sola ecuación lineal de la forma $ax + by + cz = d$ ya NO representa una recta, ¡sino un plano infinito!</strong></p>

<p>Para fijar y construir una línea recta en el espacio 3D, la intuición escalar de la pendiente colapsa. Necesitamos cambiar de herramienta analítica y apoyarnos en los <strong>vectores</strong>. Una recta en $\mathbb{R}^3$ queda unívocamente determinada cuando conocemos:</p>
<p>1. Un <strong>punto de anclaje o posición inicial</strong> en el espacio $\vec{p}$.</p>
<p>2. Un <strong>vector director</strong> que señala la orientación del desplazamiento $\vec{d}$.</p>

\begin{pregunta}
Si una sola ecuación lineal en $\mathbb{R}^3$ produce un plano, ¿cómo podemos combinar vectores para describir una línea recta precisa en el espacio, y qué ocurre cuando dos trayectorias en 3D nunca se tocan pero tampoco apuntan en la misma dirección?
\end{pregunta}

<p><strong>Aplicaciones de Alto Impacto en Ingeniería y Ciencia</strong></p>

<p><strong>1. Control de Tráfico Aéreo y Prevención de Colisiones (TCAS):</strong> Las trayectorias de dos aeronaves comerciales se modelan como rectas en $\mathbb{R}^3$. En la pantalla 2D del controlador aéreo sus rutas parecen cruzarse, pero en el espacio 3D vuelan a diferentes altitudes. Son <em>rectas alabeadas</em>: no son paralelas, pero jamás se intersectan. Los algoritmos de aviación calculan la distancia mínima entre ambas rectas para garantizar márgenes de seguridad.</p>

<p><strong>2. Gráficos por Computador (Ray Tracing):</strong> En videojuegos de última generación y cine animado, cada píxel fotorrealista se genera calculando la trayectoria de un "rayo de luz" (una recta paramétrica en $\mathbb{R}^3$: $\vec{x}(\lambda) = \vec{p} + \lambda \vec{d}$) emitido desde una cámara virtual para hallar la intersección exacta con las mallas 3D de la escena.</p>

<p><strong>3. Guiado Láser e Ingeniería Civil:</strong> En la construcción de túneles subterráneos que se excavan desde extremos opuestos de una montaña, se utilizan rayos de luz láser (rectas en $\mathbb{R}^3$) para verificar la alineación perfecta y evitar desviaciones ortogonales antes de la unión de los frentes.</p>

\begin{pregunta}
A lo largo de este capítulo responderemos algebraicamente: ¿Cómo representar una recta mediante ecuaciones vectoriales, paramétricas y simétricas? ¿Cómo determinar mediante sistemas de ecuaciones si dos rectas se cortan, son paralelas o son alabeadas? ¿Y cómo calcular la distancia mínima exacta de un punto a una recta?
\end{pregunta}
\end{card}

chapters.teoria:
\begin{card}
\begin{definicion}{Ecuación vectorial de la recta, vector posición y director}
Dado un punto fijo $\vec p=(p_1, p_2, p_3) \in \mathbb{R}^3$ llamado \textbf{vector posición} y un vector no nulo $\vec{d} = (d_1, d_2, d_3) \neq \vec{0}$ llamado \textbf{vector director}, la recta $L$ que pasa por $\vec p$ en la dirección de $\vec{d}$ es el conjunto de todos los puntos $\vec x=(x, y, z) \in \mathbb{R}^3$ que satisfacen$$\vec{x} = \vec{p} + \lambda \vec{d}.$$donde el escalar $\lambda$ recibe el nombre de \textbf{parámetro}. La forma de arriba se llama \textbf{ecuación vectorial} de la recta. Expresando los vectores en componentes cartesianas,  adopta la forma:
$$(x, y, z) = (p_1, p_2, p_3) + \lambda (d_1, d_2, d_3), \quad \lambda \in \mathbb{R}$$Al igualar componente a componente la ecuación vectorial, obtenemos las \textbf{ecuaciones paramétricas} de la recta:
$$\begin{cases} 
x = p_1 + \lambda d_1 \\ 
y = p_2 + \lambda d_2 \\ 
z = p_3 + \lambda d_3 
\end{cases}$$
\end{definicion}

\begin{definicion}{Ecuaciones Simétricas o Cartesianas}
Si todas las componentes del vector director son distintas de cero ($d_1 \neq 0$, $d_2 \neq 0$ y $d_3 \neq 0$), podemos despejar el parámetro $\lambda$ en cada una de las ecuaciones paramétricas e igualar las expresiones:
$$\lambda = \frac{x - p_1}{d_1} = \frac{y - p_2}{d_2} = \frac{z - p_3}{d_3}$$Obteniendo la forma continua o \textbf{ecuación simétrica}:
$$\frac{x - p_1}{d_1} = \frac{y - p_2}{d_2} = \frac{z - p_3}{d_3}$$
\end{definicion}



