<script>
(function() {
  const container = document.getElementById('containerRecta3D');
  const wrapper = document.getElementById('wrapperRecta3D');
  const canvas = document.getElementById('canvasRecta3D');
  const ctx = canvas.getContext('2d');
  const sliderLambda = document.getElementById('sliderLambdaRecta');
  const valLambda = document.getElementById('valLambdaRecta');
  const infoRecta = document.getElementById('infoRecta3D');

  // Etiquetas KaTeX flotantes
  const lblP0 = document.getElementById('labelP0_recta');
  const lblX = document.getElementById('labelX_recta');
  const lblD = document.getElementById('labelD_recta');
  const lblL = document.getElementById('labelL_recta');

  // Geometría
  const P0 = { x: 2.0, y: 1.0, z: 2.0 };
  const D  = { x: 1.5, y: 2.0, z: 1.5 };
  let lambda = parseFloat(sliderLambda.value);

  // Cámara (Estándar 1 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  // Dibujo de línea 3D
  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }

  // Dibujo de vector 3D con punta de flecha
  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // Dibujo del punto 3D
  function drawPoint3D(pt, color, radius = 4) {
    const p = project3D(pt.x, pt.y, pt.z);
    ctx.save();
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.arc(p.px, p.py, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  // Rejilla del plano z = 0 (Estándar 1)
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -2; i <= 5; i++) {
      const pA1 = project3D(i, -2, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

      const pB1 = project3D(-2, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }

  // Ejes Coordenados 3D (Estándar 1: Negros Sólidos)
  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);
  }

  // Función Principal de Renderizado
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();

    const X = {
      x: P0.x + lambda * D.x,
      y: P0.y + lambda * D.y,
      z: P0.z + lambda * D.z
    };

    // Recta L Infinito Punteada
    const lamMin = -2.5;
    const lamMax = 3.5;
    const pL1 = { x: P0.x + lamMin * D.x, y: P0.y + lamMin * D.y, z: P0.z + lamMin * D.z };
    const pL2 = { x: P0.x + lamMax * D.x, y: P0.y + lamMax * D.y, z: P0.z + lamMax * D.z };
    drawLine3D(pL1, pL2, '#e11d48', 2.0, [6, 4]);

    /* ========================================================================
       PROYECCIONES VERTICALES (COMENTADAS A PETICIÓN DEL USUARIO)
       ======================================================================== */
    // 1. Proyección vertical de P0 hacia el plano z = 0
    // drawLine3D(P0, { x: P0.x, y: P0.y, z: 0 }, '#94a3b8', 1.2, [3, 3]);

    // 2. Proyección vertical de X hacia el plano z = 0
    // drawLine3D(X, { x: X.x, y: X.y, z: 0 }, '#94a3b8', 1.2, [3, 3]);

    // Vectores Principales
    drawVector3D({ x: 0, y: 0, z: 0 }, P0, '#0284c7', 2.2);

    const P0_plus_D = { x: P0.x + D.x, y: P0.y + D.y, z: P0.z + D.z };
    drawVector3D(P0, P0_plus_D, '#059669', 2.5);
    drawVector3D({ x: 0, y: 0, z: 0 }, X, '#d97706', 2.2);

    drawPoint3D(P0, '#0284c7', 5);
    drawPoint3D(X, '#d97706', 5);
    drawPoint3D(P0_plus_D, '#059669', 4);

    // ETIQUETAS KATEX FLOTANTES EN EL ESPACIO 3D
    const posP0 = project3D(P0.x, P0.y, P0.z);
    const posX  = project3D(X.x, X.y, X.z);
    const posD  = project3D(P0.x + D.x * 0.5, P0.y + D.y * 0.5, P0.z + D.z * 0.5);
    const posL  = project3D(pL2.x, pL2.y, pL2.z);

    if (lblP0) { lblP0.style.left = posP0.px + 'px'; lblP0.style.top = (posP0.py - 12) + 'px'; }
    if (lblX)  { lblX.style.left  = posX.px + 'px';  lblX.style.top  = (posX.py - 12) + 'px'; }
    if (lblD)  { lblD.style.left  = posD.px + 'px';  lblD.style.top  = (posD.py - 14) + 'px'; }
    if (lblL)  { lblL.style.left  = posL.px + 'px';  lblL.style.top  = (posL.py - 10) + 'px'; }

    if (infoRecta) {
      infoRecta.innerHTML = `\\(\\vec{x} = (${X.x.toFixed(2)}, ${X.y.toFixed(2)}, ${X.z.toFixed(2)})\\)`;
      if (window.renderMathInElement) {
        window.renderMathInElement(infoRecta, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  sliderLambda.addEventListener('input', (e) => {
    lambda = parseFloat(e.target.value);
    valLambda.textContent = lambda.toFixed(1);
    draw();
  });

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con la Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas Teclado
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderLambda) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones Vistas Ortogonales
