  let panX = 0;
  let panY = 0;
  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };
  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;
    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;
    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;
    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }
  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }
  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;
    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  function drawPoint3D(pt, color, radius = 4) {
    const p = project3D(pt.x, pt.y, pt.z);
    ctx.save();
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.arc(p.px, p.py, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -1; i <= 5; i++) {
      const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);
      const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }
  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z
    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);
    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);
  }
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawGrid3D();
    drawAxes3D();
    // Punto genérico P(lambda) sobre la recta L
    const P_curr = {
      x: P0.x + lambda * D.x,
      y: P0.y + lambda * D.y,
      z: P0.z + lambda * D.z
    };
    // Tramo de la Recta L
    const L_start = { x: P0.x - 1.0 * D.x, y: P0.y - 1.0 * D.y, z: P0.z - 1.0 * D.z };
    const L_end   = { x: P0.x + 2.5 * D.x, y: P0.y + 2.5 * D.y, z: P0.z + 2.5 * D.z };
    drawLine3D(L_start, L_end, '#0284c7', 2.2);
    // Vector Director d aplicado en P0
    const D_end = { x: P0.x + D.x, y: P0.y + D.y, z: P0.z + D.z };
    drawVector3D(P0, D_end, '#059669', 2.5);
    // Vector w(lambda) = q - P(lambda) entre el punto genérico y q
    drawLine3D(P_curr, Q, '#8b5cf6', 2.0, [5, 4]);
    // Punto Exterior Q
    drawPoint3D(Q, '#8b5cf6', 6);
    // Punto Inicial P0
    drawPoint3D(P0, '#0284c7', 4.5);
    // Distancia actual d(lambda)
    const distCurr = Math.hypot(Q.x - P_curr.x, Q.y - P_curr.y, Q.z - P_curr.z);
    const isOptimal = Math.abs(lambda - lambdaOpt) < 0.03;
    if (isOptimal) {
      // Dibujar Pie de la Perpendicular P* destacado
      drawPoint3D(P_opt, '#e11d48', 6.5);
      drawLine3D(P_opt, Q, '#e11d48', 2.5);
      // Dibujar Indicador de Ángulo Recto 90º en 3D entre (Q - P*) y d
      const lenW = Math.hypot(Q.x - P_opt.x, Q.y - P_opt.y, Q.z - P_opt.z);
      const lenD = Math.hypot(D.x, D.y, D.z);
      const uD = { x: D.x / lenD, y: D.y / lenD, z: D.z / lenD };
      const uW = { x: (Q.x - P_opt.x) / lenW, y: (Q.y - P_opt.y) / lenW, z: (Q.z - P_opt.z) / lenW };
      const s = 0.35;
      const c1 = { x: P_opt.x + s * uD.x, y: P_opt.y + s * uD.y, z: P_opt.z + s * uD.z };
      const c2 = { x: P_opt.x + s * uD.x + s * uW.x, y: P_opt.y + s * uD.y + s * uW.y, z: P_opt.z + s * uD.z + s * uW.z };
      const c3 = { x: P_opt.x + s * uW.x, y: P_opt.y + s * uW.y, z: P_opt.z + s * uW.z };
      const pC1 = project3D(c1.x, c1.y, c1.z);
      const pC2 = project3D(c2.x, c2.y, c2.z);
      const pC3 = project3D(c3.x, c3.y, c3.z);
      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#e11d48';
      ctx.lineWidth = 1.8;
      ctx.moveTo(pC1.px, pC1.py);
      ctx.lineTo(pC2.px, pC2.py);
      ctx.lineTo(pC3.px, pC3.py);
      ctx.stroke();
      ctx.restore();
      if (lblPopt) {
        lblPopt.style.display = 'block';
        const pOpt2D = project3D(P_opt.x, P_opt.y, P_opt.z);
        lblPopt.style.left = pOpt2D.px + 'px';
        lblPopt.style.top  = (pOpt2D.py - 16) + 'px';
      }
    } else {
      // Dibujar punto móvil sobre la recta L
      drawPoint3D(P_curr, '#38bdf8', 5);
      if (lblPopt) lblPopt.style.display = 'none';
    }
    // Actualizar Posiciones de Etiquetas KaTeX Flotantes
    const posQ  = project3D(Q.x, Q.y, Q.z);
    const posP0 = project3D(P0.x, P0.y, P0.z);
    const posD  = project3D(P0.x + D.x * 0.5, P0.y + D.y * 0.5, P0.z + D.z * 0.5);
    const posL  = project3D(L_end.x, L_end.y, L_end.z);
    if (lblQ)  { lblQ.style.left  = posQ.px + 'px';  lblQ.style.top  = (posQ.py - 14) + 'px'; }
    if (lblP0) { lblP0.style.left = posP0.px + 'px'; lblP0.style.top = (posP0.py - 12) + 'px'; }
    if (lblD)  { lblD.style.left  = posD.px + 'px';  lblD.style.top  = (posD.py - 12) + 'px'; }
    if (lblL)  { lblL.style.left  = posL.px + 'px';  lblL.style.top  = (posL.py - 10) + 'px'; }
    // Actualizar Panel de Información KaTeX Overlay
    if (infoOverlay) {
      if (isOptimal) {
        infoOverlay.innerHTML = `
          <div style="color: #e11d48; font-weight: 700; margin-bottom: 2px;">¡Pie de la Perpendicular \\(\\vec{p}_*\\) Hallado!</div>
          <div style="color: #334155; font-size: 12px;">\\(\\lambda^* = \\frac{(\\vec{q} - \\vec{p}) \\cdot \\vec{d}}{\\|\\vec{d}\\|^2} = \\frac{5}{6} \\approx ${lambdaOpt.toFixed(3)}\\)</div>
          <div style="color: #334155; font-size: 12px; margin-top: 2px;">\\(\\vec{p}_* = (${P_opt.x.toFixed(2)}, ${P_opt.y.toFixed(2)}, ${P_opt.z.toFixed(2)})\\)</div>
          <div style="color: #e11d48; font-weight: bold; font-size: 12px; margin-top: 2px;">\\(d(\\vec{q}, L) = \\text{Mínima} = ${distCurr.toFixed(3)}\\) \\(\\quad (90^\\circ)\\)</div>
        `;
      } else {
        infoOverlay.innerHTML = `
          <div style="color: #0284c7; font-weight: 700; margin-bottom: 2px;">Punto Móvil en la Recta \\(L\\)</div>
          <div style="color: #334155; font-size: 12px;">\\(\\lambda = ${lambda.toFixed(2)}\\) \\(\\quad\\) (Buscando \\(\\lambda^* \\approx 0.83\\))</div>
          <div style="color: #334155; font-size: 12px; margin-top: 2px;">\\(L(\\lambda) = (${P_curr.x.toFixed(2)}, ${P_curr.y.toFixed(2)}, ${P_curr.z.toFixed(2)})\\)</div>
          <div style="color: #8b5cf6; font-size: 12px; margin-top: 2px;">Distancia actual: \\(d = ${distCurr.toFixed(3)}\\)</div>
        `;
      }
      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }
  // Slider de lambda
  slider.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    lambda = parseFloat(e.target.value);
    valLambda.textContent = lambda.toFixed(2);
    draw();
  });
  // Animación del parámetro lambda
  function animateToOptimal() {
    if (isAnimating) {
      stopAnimation();
      return;
    }
    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    let currentL = parseFloat(slider.value);
    const targetL = lambdaOpt;
    const speed = 0.015;
    function stepAnim() {
      if (!isAnimating) return;
      if (Math.abs(currentL - targetL) < speed) {
        currentL = targetL;
        lambda = currentL;
        slider.value = lambda;
        valLambda.textContent = lambda.toFixed(2);
        draw();
        stopAnimation();
        return;
      }
      currentL += (targetL > currentL ? 1 : -1) * speed;
      lambda = currentL;
      slider.value = lambda;
      valLambda.textContent = lambda.toFixed(2);
      draw();
      animId = requestAnimationFrame(stepAnim);
    }
    stepAnim();
  }
  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Animación';
  }
  btnAnim.onclick = animateToOptimal;
  document.getElementById('btnOptimalPie').onclick = () => {
    if (isAnimating) stopAnimation();
    lambda = lambdaOpt;
    slider.value = lambdaOpt;
    valLambda.textContent = lambdaOpt.toFixed(2);
    draw();
  };
  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });
  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;
    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));
    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });
  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });
  // Zoom con la Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;
    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);
    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;
      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }
    zoom = newZoom;
    draw();
  }, { passive: false });
  // Traslación con Flechas Teclado
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === slider) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });
  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_pie').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_pie').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_pie').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_pie').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };
  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_pie').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };
  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';
      const controlsHeight = 120;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;
      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';
      wrapper.style.width = '620px';
      wrapper.style.height = '400px';
      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }
  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);
  draw();
})();
</script>
\end{html}

chapters.motivacion:
\begin{card}
\textbf{¿Cómo modelamos el espacio?}

<p>Imagina que estás en tu habitación en este instante. Si quisiéramos registrar la temperatura en cada rincón, no nos basta con un único número. La temperatura varía si te acercas a la ventana, si subes al techo o si te sientas en el suelo.</p>
<p>Para describir esto matemáticamente, debemos asignar a cada coordenada espacial $(x, y, z)$ un único valor térmico $T$. Así, la temperatura es una función $T(x,y,z)$.</p> 
<p>\textbf{Concepto clave:} Un campo escalar es simplemente una regla que le asigna un único número real (temperatura, presión, altitud, densidad) a cada punto del espacio.</p>
\begin{pregunta}
    ¿Cómo cambia el cálculo cuando una función depende de más de una variable?
  \end{pregunta}
\end{card}

chapters.teoria:
\begin{card}
Para transitar del cálculo en una variable al cálculo multivariable, debemos formalizar matemáticamente la noción de asignar valores numéricos a puntos en el espacio. A continuación, estableceremos los pilares algebraicos de los campos escalares.
  \begin{definicion}{Campo Escalar}
    Un \textbf{campo escalar} (o función de varias variables) es una función $f$ que asigna a cada elemento o punto $\vec{x} = (x_1, x_2, \dots, x_n)$ de un subconjunto $D \subseteq \mathbb{R}^n$ un único número real denotado por $f(\vec{x})$ o $f(x_1, x_2, \dots, x_n)$.

    Matemáticamente lo expresamos como:
    $$ f : D \subseteq \mathbb{R}^n \to \mathbb{R} $$
    Donde $n$ representa la dimensión del espacio de entrada (habitualmente $n=2$ o $n=3$).
  \end{definicion}

  \begin{definicion}{Dominio de un Campo Escalar}
    El \textbf{dominio} de un campo escalar $f$, denotado por $\operatorname{dom}(f)$, es el conjunto de todos los puntos en $\mathbb{R}^n$ para los cuales la regla de correspondencia de la función produce un número real bien definido. 

    Formalmente se define como:
    $$ \operatorname{dom}(f) = \{ \vec{x} \in \mathbb{R}^n : f(\vec{x}) \in \mathbb{R} \} $$
    Si el dominio no se especifica explícitamente, se asume que es el \textit{dominio natural}, es decir, el conjunto más grande posible de puntos donde la expresión matemática es válida.
  \end{definicion}

\begin{trampa}{Visualización del Dominio}
\error{Pensar que el dominio es un intervalo}
    \correct{En Cálculo en una variable el dominio es subconjunto de los reales, por ejemplo invervalos, pero en Cálculo Multivariable el dominio es una \textbf{región geométrica} en el plano $XY$ ($\mathbb{R}^2$), en el espacio $XYZ$ ($\mathbb{R}^3$) o en hiperespacios de mayor dimensión.}
\end{trampa}

\begin{definicion}{Imagen o Recorrido}
La \textbf{imagen} (o recorrido) de un campo escalar $f$, denotada por $\operatorname{im}(f)$ o $\text{rec}(f)$, es el conjunto de todos los valores reales que la función efectivamente toma a medida que evaluamos todos los puntos pertenecientes al dominio.

    Formalmente se define como:
    $$ \operatorname{im}(f) = \{ y \in \mathbb{R} : y = f(\vec{x}) \text{ para algún } \vec{x} \in \operatorname{dom}(f) \} $$
  \end{definicion}



\begin{metodo}{Determinación de Dominios en Campos Escalares}

\problema{Aplicar las restricciones algebraicas clásicas para encontrar la región matemática que define el dominio natural de distintos campos escalares en $\mathbb{R}^2$.}

\paso{1}{Restricción por Denominadores}
El denominador de una expresión fraccionaria debe ser distinto de cero ($g(\vec{x}) \neq 0$) para evitar divisiones indefinidas.
\ejemplo{Para $f(x,y) = \frac{3xy}{x-y}$, exigimos $x-y \neq 0 \Rightarrow y \neq x$. 

El dominio es todo el plano $\mathbb{R}^2$ excepto los puntos sobre la recta diagonal $y=x$.}

\paso{2}{Restricción por Raíces de Índice Par}
El radicando de cualquier raíz cuadrada o de índice par debe ser mayor o igual a cero ($g(\vec{x}) \geq 0$) para operar en los números reales.
\ejemplo{Para $f(x,y) = \sqrt{4 - x^2 - y^2}$, requerimos $4 - x^2 - y^2 \geq 0 \Rightarrow x^2 + y^2 \leq 4$

El dominio es la región interior y la frontera de un círculo de radio 2 centrado en el origen.}

\paso{3}{Restricción por Logaritmos}
El argumento de cualquier función logarítmica debe ser estrictamente positivo ($g(\vec{x}) > 0$).
\ejemplo{Para $f(x,y) = \ln(y - x^2)$, necesitamos $y - x^2 > 0 \Rightarrow y > x^2$. 

El dominio es la región abierta que está estrictamente por encima de la parábola $y=x^2$ (excluyendo la curva).}

\end{metodo}
\end{card}

chapters.motivacion:
\begin{card}
Imagina que estás planeando una expedición a la cordillera. Tienes un mapa impreso completamente plano, pero necesitas saber dónde están los acantilados más empinados y dónde se encuentran las llanuras seguras para caminar. ¿Cómo puede un simple trozo de papel de dos dimensiones mostrarte el relieve tridimensional?

La respuesta que encontraron los topógrafos hace siglos son las líneas de contorno. Cada línea en el mapa conecta todos los puntos que están exactamente a la misma altitud. Si caminaras físicamente siguiendo esa línea, no subirías ni bajarías; te mantendrías al mismo "nivel".

En matemáticas, hacemos exactamente lo mismo. Tomamos un grafo tridimensional (una superficie 
) y lo "rebanamos" con planos horizontales a distintas alturas constantes (
). Al proyectar esos cortes hacia el suelo bidimensional, obtenemos un mapa de curvas de nivel que nos revela los secretos del espacio.
\end{card}

